quests[83144] = { id = 83144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodletting", description = "The land aches underfoot. These pipes carry Black Blood north in a massive volume!\n\nI've never seen the land become infected this rapidly. Clear away the rot--perhaps we can save it yet.\n\nI'll go after the structures. Point out weak spots as you find them and I will focus our assault!", progress = "The horrors these goblins have brought forth are truly a blight on this land.", completion = "I mistrust any of the goblins responsible for this pipeline.\n\nBe cautious, {name}.", objectives = "Kill Black Blood creatures and signal Orweyna to attack weak points in the pipeline.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83145] = { id = 83145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paranoia Prevention", description = "What information is Gallywix after here in Gutterville? Let's see if some of these goblins will give us a hint. \n\nLet's start with any Bilgewater goblins we can find.", progress = "This seems like it's more about keeping people quiet than actually learning anything.", completion = "I hope Renzik catches up with Zirdo before he can blab, but we shouldn't count on it.", objectives = "Investigate Gutterville's spy problem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83146] = { id = 83146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pamsy's Prized Pump", description = "I got a team of engineers. All of them got families. They keep having horrible accidents and infections from the Black Blood. I just couldn't stand another death. I opened the wall. I wanted it to bring us some hope.\n\nYou show up and want to stop the Black Blood. It doesn't do anythin' good to stop these pipes up here. We gotta get to the pump station.\n\nSo, my crew and the pumps? They're all at the same station. But we should hurry.", completion = "I can't believe it. Zirdo must have told Overseer Gozzic about me. This is a clear message to stop...", objectives = "Go to the pump station and meet Pamsy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83147] = { id = 83147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloody Business", description = "The horrors of the Black Blood here cannot be underestimated. The strength of it in this place is causing my visions to feel distant, like odd whispers.\n\nKill the manifestations of this rot, before they grow stronger.", progress = "I cannot ignore this blight on the land.", completion = "It will take much more to staunch these wounds. We must not tire.", objectives = "Kill blood horrors for Orweyna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83148] = { id = 83148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "X-Treme Chill", description = "Pamsy and I came up with an idea. Since we can't access the controls, and we can't blow it up, what if we freeze the pump station?\n\nStay with me!\n\nPamsy mentioned that a lot of the machines up north are overheating lately, because all the coolant is being used down south. And it's even harder to get, because the blood slimes eat it. What if we found all of that coolant supply and dumped it into the pump station? \n\nWe put the whole operation on ice, and it'd take ages to fix!", progress = "Get enough to freeze this station solid!", completion = "Great, that's a good haul!", objectives = "Kill Chillgut Slimes to collect Chillburst Canisters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83149] = { id = 83149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avenge Them", description = "I followed Zirdo's trail south. I found a nasty piece o' work named Gozzic Cogcrane pushin' workers around and talking about \"another lesson.\" Zirdo must have snitched to this Gozzic guy, but I need to confirm it. I think this Gozzic will have the proof on him.\n\nGozzic could've given the orders, but lookin' at that bloody shredder and the marks on Pamsy's crew, I'm sure he got involved personally. You should do the same. Kill Gozzic and check him for any sign Zirdo got word to him.", progress = "These engineers deserved better.", completion = "You found proof? I knew it. Not as good as getting Zirdo himself, but we'll catch up with him in the end.", objectives = "Kill the Darkfuse that killed Pamsy's engineers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83150] = { id = 83150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expanding the Plan", description = "Here's the plan. If we just freeze the outside, it'll all melt in a bit and go back to normal. But we got Orweyna. She can target cracks and leaks in the pipes so the coolant can get inside and really muck things up.  \n\nSince you gathered all the canisters, I think you should get the honor of freezing the pipe solid.\n\nPamsy has a rocketboard, and you'll be able to dispense icy justice down upon the station's key areas. Follow Orweyna!", progress = "Hop onto the rocketboard and shoot away!", completion = "Nice ice work! Ha!", objectives = "Ride the rocketboard and shoot the pipeline with ice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83151] = { id = 83151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down Undermine", description = "We've done what we could here. It's time to get a look at Undermine.\n\nPamsy's got a contact, a Venture goblin named Grimla. We can start there when we arrive.\n\nLet's get Gazlowe and get going. Undermine's not the kinda problem you solve with a knife. We need someone like Gazlowe on board for this. You know, the builder and leader type.", completion = "I hope Renzik and Pamsy know what they're doin' with Grimla here.", objectives = "Talk with Gazlowe, then go to Undermine using the rocket drill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83152] = { id = 83152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magmanagement", description = "As if the pipe going down wasn't enough, a horde of magmatic elementals burst out when it failed.\n\nWe can't risk sending anyone else down to attempt repairs while the area is overrun, but that magma is vital to powering the whole Deeps.\n\nIf you are capable, clear them out so we can get that magma flowing again.", progress = "Is it done?", completion = "Commendable job. We could do with a little less excitement in our work.", objectives = "Kill Risen Magma and Slag Bubbles near Hallowfall Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83153] = { id = 83153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sampling Steam", description = "The effects of the magmatic buildup are clear to see, but what we still do not understand is the root cause.\n\nIn order to determine it, and prevent it in the future, I need samples of the volcanic gases you can see bursting from the ground.\n\nFresh samples. Very fresh.\n\nYou're going to have to stand in them as they erupt in order to gather what I need.", progress = "Do you have the samples?", completion = "Hopefully these samples will reveal what went wrong. Your assistance is appreciated.", objectives = "Stand in gas vents near Hallowfall Gate as they erupt to gather samples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83154] = { id = 83154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knicknack's Knickknacks", description = "Not fair! Not fair! Knicknack collect many shiny things over long life. But now stupid wax for brains Candleclaws push out Knicknack and family. Shiny things all left behind!\n\nHere, goblin friend helped made list of all my treasures inside Darkflame Cleft. You go take back!", progress = "Treasures all very important. Very valuable. You no take for you! Bring back to me!", completion = "You did it! You did it! My treasures! Take that, stupid Candleclaws.", objectives = "Retrieve Knicknack's treasures from Darkflame Cleft.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83155] = { id = 83155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tired of Tripping", description = "All that's between us and the juiciest excavation site I've ever seen is a couple of moles and a leggy deer. Sorry, getting ahead of myself.\n\nSee these shredders? State of the art in the field of maiming and killing. And they keep getting stuck in holes!\n\nListen, I'm as ecologically conscientious as the next goblin, but these moles have got to go. I'm gonna need you to give these hardheads a hard time. And if you see any of my crew, help 'em out, wontcha?", progress = "You deal with 'em yet? I'm not hauling another shredder out of the mud.", completion = "You sure sent 'em scurrying! There's only one teensy thing left between us and all those beautiful resources.", objectives = "\"Remove\" 15 Hardhead moles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83159] = { id = 83159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Off the Top", description = "Ever seen a deepstrider before? This one sure ain't happy to see us. Made quick work of the shredders that made it past the moles. Real shame, those pilots are gonna have to work overtime to pay off the damages.\n\nNow if someone were to take care of it and bring back something as proof, well, I'm sure there'd be a nice payday.", progress = "What did you do?!", completion = "This is bad, real bad! You'd think killin' something would make it less dangerous. We're getting stomped!", objectives = "Slay Alhainr and collect its skull.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83160] = { id = 83160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cinderbrew Reserve", description = "Trade may have been restricted, but I'll calcify before I let my Cinderbrew Reserve fall into the hands of these stripped screws or go up when some elemental looks at it funny.\n\nThe inspectors are watching me, stranger, so I can't go fetch it myself, but they won't be paying any special attention to you.\n\nI left it behind the desk in my old office, down below.\n\nJust don't get too close to an enforcer or they'll confiscate any cinderbrew you're carrying and I'll be left with nothing to drink.", progress = "Do you have it?", completion = "Ah, now this is a brew worth waiting for. Thank you, {name}.", objectives = "Bring the Cinderbrew Reserve to Cogwin at the Hallowfall Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83162] = { id = 83162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put it Back, Put it Back!", description = "It's going to ruin everything! Who wants to visit a resort with a thirty-foot tall ghost-deer? Ok, no need to panic. It's probably just a little miffed you took its skull.\n\nFirst, you gotta get rid of some of these slimes. Then, get that skull out of here. The farther the better.\n\nOh man, they're gonna get ectoplasm in the hot pools!", progress = "Hurry up, before this whole place is wrecked!", completion = "Whew, that was close. This whole thing has really taught me to value the beauty of nature.\n\n<The goblin breaks into laughter.>\n\nReally had you going there, huh? Still, think I'll leave Abyssal Excavation alone for awhile.", objectives = "Stomp slimes and take Alhainr's Skull away from town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83163] = { id = 83163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Split Venture", description = "We're headed to my home turf next, Venturewood. It's next to the Heaps.\n\nThe Venture Company is mostly on board for Gallywix. That means a lot of the top brass are as dirty as him. Watch your step.\n\nBut there are some good folks there too. Like Pamsy and her crew. The little guy at Venture gets it rough. Everyone thinks of Venture Co. as just the baddies, so no one looks after them. But I gotta try right?\n\nHop in the hot rod, I'll show you what I mean.", progress = "Seems like there's no respect for the little guys.", completion = "You did good for those goblins. Nikki brings the chaos--and not in the fun way.", objectives = "Ride the hot rod to the Venturewood and assist friendly Venture Co. goblins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83164] = { id = 83164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "City of Threads: Splice the Splicer", description = "\"Ascension\" is no true evolution. It is defilement. It is doom. And Ansurek further etches that doom in stone with each passing day.\n\nIf we bring down the Transformatory, then we can potentially rid Azj-Kahet of these abominations for good.\n\nIzo the Grand Splicer is Ansurek's chosen overseer of the Ascension process. Cut that wretch's head from her body, and perhaps these mutations will cease.", progress = "Have you dealt with the Transformatory, {name}?", completion = "You've dealt a blow that Ansurek will never recover from, {name}.\n\nTake this and be well.", objectives = "Enter the City of Threads and defeat Izo the Grand Splicer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83165] = { id = 83165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Badly Behaved Bot", description = "Go ahead, laugh. I would be as well if I didn't have such pressing business. My bot's foot clipped a nearby rock, spilled me out and then righted herself. Without me in the cockpit! \n\nI'm grounded while she floats there quite cheerfully. Can you believe it? \n\nListen, if you are heading up to Shadowvein Point, will you let Kagfritha know that I'll be late for my shift? I need to wait for this hunk of metal to run out of fuel and dip low enough for me to get back in the driver's seat.", completion = "Sinruna got tossed again, did she? I keep telling her she's flying too low. Maybe this'll knock some sense into her.", objectives = "Speak with Kagfritha in Shadowvein Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83166] = { id = 83166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ara-Kara, the City of Echoes: Harvest's End", description = "You've seen it yourself, haven't you? The \"Black Blood,\" as we call it.\n\nWe will not stand idle any longer. Not while Ansurek mutilates, drills, and exsanguinates our precious land for the last, fetid dribbles of the old gods' death rattle. \n\nSeek out the old city beneath us--Ara-Kara, The City of Echoes. You will receive a handsome bounty should you slay the crony in charge of the excavation. Her people call her Ki'katal, the Harvester.", progress = "Have you been to Ara-Kara yet?", completion = "Ki'katal is dead? Excellent.\n\nYou have our thanks, {name}. In both praise, and material value.", objectives = "Enter the Ara-Kara, The City of Echoes and defeat Ki'katal the Harvester.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83167] = { id = 83167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes from Above", description = "That was rough, with Nikki. And worse, those Darkfuse spy-copters saw everything. Feels like we can't get away from all the spies, don't it?\n\nThe last thing Venture needs is Gallywix thinking these workers ain't loyal 'cause they got caught on footage during one of Nikki's tantrums. We don't want a repeat of what happened to my last crew. \n\nGo take the footage from the spy-copters. They usually lurk around the workshops, or follow Venture workers around.", progress = "There is nothing better than breaking bad machines for a good cause.", completion = "The less dirt on us Gallywix has, the better.", objectives = "Kill 8 Spy-Copters to steal their footage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83168] = { id = 83168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trail of Black Blood", description = "While you have been getting familiar with the state of Undermine, I have been tracking our prey. The presence of Black Blood is everywhere, hidden behind noisy distractions.\n\nBut this city cannot fool me. I discovered a Black Blood shipment at a place called Hovel Hill, but there were machines guarding it. We should go together.", progress = "Tracking the shipments should show us who's using 'em. Check out any labels or letters layin' around!\n\nI think I stunned all of the defenses, they'll leave us be.", completion = "Baron Revilgaz is shipping Black Blood around the city? And he's paranoid about Ethereals?!\n\nI got questions, and he's got answers.", objectives = "Investigate Hovel Hill for Black Blood shipments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83169] = { id = 83169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Long Way from Booty Bay", description = "There is no doubt about it. These shipments have Blackwater Cartel written all over them... literally. The Black Blood comes in here and then Blackwater takes it somewhere in the city by couriers.\n\nSo if we want to find out where, we go right to the top--Baron Revilgaz. Grimla mentioned Revilgaz has a temporary set up nearby, here in Hovel Hill. Let's go pay him a visit.\n\nThe ethereal thing will have to wait.", progress = "I have a bad feeling about all this, but let's talk to Revilgaz.", completion = "I am sure we can come to an understanding.", objectives = "Locate Baron Revilgaz at Hovel Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83170] = { id = 83170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Again!", description = "The Darkfuse are moving into Hovel Hill. It's the same thing they did at Blackwater Marina. Once they move in, they start pushing the locals around. Sometimes they just make 'em go away. It ain't right. I want to fight back, but my hands are tied.\n\nIf an outsider showed up and started making trouble, that'd be a different story.", progress = "Fairness is a loose concept in Undermine, but the Darkfuse push it too far.", completion = "If I had a few more like you I wouldn't have lost my... the marina.", objectives = "Make trouble with the Darkfuse in Hovel Hill for Revilgaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83171] = { id = 83171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye Sores for Sore Eyes", description = "They call them recruitment posters, but that ain't all they're for. They're there to remind everyone the Darkfuse are in charge and can do whatever they want. If me or one of the locals rip 'em down, it goes bad for us. \n\nBut the Darkfuse hate you anyway. \n\nIf you torched all the posters, I would owe you one.", progress = "I'm sick of seeing those recruitment posters. Burn them.", completion = "It may not keep Darkfuse out, but at least Hovel Hill is a little nicer without that Darkfuse garbage on the walls. \n\nLike I said, I owe ya one.", objectives = "Burn 8 Darkfuse Recruitment Posters on and around Revilgaz's house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83172] = { id = 83172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Blood Baton Pass", description = "Blackwater is just one step on the journey, and they like to keep this stuff moving. Revilgaz has his people take it from the station, hide it for a bit, then deliver it to the drop sites. The drop sites change, but the current one is a depot in the Heaps.\n\nWe're gonna check it out and find out where the Black Blood goes from there.\n \nHe says it's guarded, so look for us out near the edge.", completion = "That's a lot of guards. We're on to something.", objectives = "Meet with Renzik and Gazlowe at the next Black Blood depot in the Heaps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83173] = { id = 83173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing Out the Depot", description = "The Heaps are crawling with guards. We've got an opportunity to disrupt the Black Blood operation in Undermine and we should take it.\n\nWe can't stop all the Black Blood from getting around the city, but we can clear out some guards and smash some shipments. Mess them up enough to disrupt things. Every little bit helps.", progress = "Every guards or shipment lost costs them time and money. And Gallywix hates losing both.", completion = "That should slow the Black Blood business. Hopefully anyone expecting a shipment will have a real bad day.", objectives = "Clear the depot area in the Heaps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83174] = { id = 83174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Good Pal", description = "Our old pal Zirdo's back. It looks like he's been promoted to Overseer of the Heaps, keeping track of the Black Blood shipments.\n\nWe owe him some payback for sellin' us out in Gutterville. He got a lot of good goblins killed to get on Gallywix's good side. Give the little snitch what he deserves.", completion = "I ain't forgot what he did to Pamsy's crew in Gutterville... This was for them too.", objectives = "Kill Zirdo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83175] = { id = 83175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another Piece of the Puzzle", description = "<The ledger has longwinded ramblings about Zirdo's achievements, but also contains various deliveries of Black Blood across Undermine. Multiple entries in the ledger stick out as odd:\n\n- One thousand units for Secret Project, Deliver to Secret Project Site.\n- Twenty units for Developmental Ammunition, Deliver via Courier.\n\nTransfers approved by Noggenfogger of Steamwheedle.>", progress = "Noggenfogger knows better than to get mixed up with Gallywix.", completion = "This is all too much.", objectives = "Discuss the contents of Zirdo's Ledger with Gazlowe in the Heaps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83176] = { id = 83176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Hunch", description = "It's time to sort out what to do next. This Noggenfogger business has Gazlowe on edge and we gotta move quickly to find out what's going on. \n\nSomething's got me on edge too. We should get outta the Heaps fast. But let's make sure Gazlowe's on board.", completion = "Grimla says Orweyna and Alleria haven't shown up.", objectives = "Check in with Renzik about Gazlowe, and then meet Gazlowe outside of the Heaps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83177] = { id = 83177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Socialized Medicine", description = "It has come to my attention that the most downtrodden residents of the Burrows have fallen prey to some sort of malady.\n\nTake this potion and dose the sick. This will strengthen the citizens and curtail further outbreak.", progress = "Have you aided the residents of the Burrows?", completion = "I will not allow their suffering.", objectives = "Dose Downtrodden Residents with Nizrek's potion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83178] = { id = 83178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rules and Consequences", description = "I fear I have grown too brazen in my offerings of succor as of late. I seem to have attracted some untoward eyes.\n\nBe on guard. A veiled threat looms.", progress = "Have you handled the interloper?", completion = "Thank you for your aid. I am a great mind, but my acuity for combat is less impressive.\n\nStill, if Ansurek's assassins have found me...\n\nNo. I cannot stop now. I have too much yet to do.", objectives = "Defeat the Assassin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83181] = { id = 83181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Best Friends, Same Ends", description = "I saw the shipwright leave the cave and head down to the beach. She was accompanied by a formidable looking nerubian.\n\nThe shipwright is the mastermind behind this entire operation. She knows precisely how the lumber is to be cut and what lumber is needed for their airships.\n\nThe nerubians know this and likely assigned one of their best to protect her.\n\nIf we can eliminate the shipwright, we can bring all of their carefully laid plans to ruin.", progress = "Is it done {name}?", completion = "With the nerubian leader destroyed, their remaining forces will be in disarray.\n\nWithout the shipwright's knowledge and leadership, their entire operation will be crippled. \n\nLet us hope it also drives a wedge between these hopefully former friends.", objectives = "Eliminate Shipwright Isaebela and Shadowspinner Azarak at Silkwood Grotto.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83182] = { id = 83182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bloody Inheritance", description = "When the kobyss killed my parents, they stole some of their most cherished things. \n\nNot me, obviously. Cherished items. \n\nWhile we are murdering kobyss, let's find them.", progress = "Stupid kobyss. I hate them.", completion = "Well done. Far more useful than those other adults who told me not to do this.\n\n\"But Alyza, the kobyss are dangerous. You'll die.\" Stupid adults, thinking they know best.\n\nAre you ready to kill the big one? I'm ready to kill the big one.", objectives = "Retrieve Alyza's parents' items in the Hungering Pool in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83194] = { id = 83194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under Fire", description = "I'm only standing here because of Renzik. He didn't even think about it--he just...", progress = "We're not finished here.", completion = "<Gazlowe wears an expression you've never seen before. His face is etched with anger, yet he speaks with a deadly calm.>\n\nThere's no more denying it--it's Gallywix, or it's us. We can't put up with him, not for a day longer. He needs to be stopped. No more compromises, no more patience.", objectives = "Be there for Monte Gazlowe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83195] = { id = 83195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rally the People", description = "No one's been stepped on harder by Gallywix than the Bilgewater Cartel. Plenty already want to rise up, but that ain't enough. We gotta show them what Gallywix has done and convince them that now is the time.\n\nLet's start with a headline. C'mon, pitch me. A big shot like you carries our message better than anyone else.", progress = "Now is the time to rise up. Tell 'em, {name}.", completion = "There's change in the air. I can feel it.", objectives = "Pick a headline with Dirk Greasedealer and then spread the word of revolution in Tailgate Park.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83196] = { id = 83196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disperse!", description = "Gallywix can't hide the truth, but he can beat us down until folks have no choice but to accept it. We ain't lettin' that happen again.\n\nYou see someone hurting a Bilgewater goblin, return the favor.", progress = "The people have to know the streets are safe. It's on us to make them so.", completion = "The time for talking this out is long past. If they're with Gallywix, that's on them.", objectives = "Kill 20 Darkfuse at Tailgate Park.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83197] = { id = 83197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Owns the Streets?", description = "Her! Nikki the Fixer, Venture Company's top enforcer. Renzik's blood is on her hands.\n\nI can't worry if she's got another bullet. We gotta go after her. You with me, {name}?", completion = "You made it just in time to join the boarding party.", objectives = "Confront Renzik's killer, Nikki the Fixer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83198] = { id = 83198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Backyard Navy", description = "Gallywix and his crew have been meddling in our business for too long. Look at what they're doing to my marina! So comfortable with their holdings that they're doing donuts on jetskis!\n\nIt's time we introduce them to a little high seas firepower.\n\nTake this cannon and blow those Darkfuse vessels skimming our waters sky-high. After that, do me a favor and check up on the big guy, won't ya?", progress = "Did my Captain send you? He knew I'd need help...", completion = "Hrrk. The roar of cannonfire and the scent of black powder. You'd make a fine cannoneer.", objectives = "Destroy the Darkfuse Joyriders in the Blackwater Marina.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83199] = { id = 83199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Been Savin' This One", description = "Listen {name}, Sprinkle's been cooking something for a long time that I'm finally ready to cash in. A little alchemist's secret ingredient. Citrus! Delivers twice the kick of Noggenfogger's Restorative Elixirs at half the speed. Strengthens your bones, grows your muscles, does your taxes. The whole nine yards!\n\nProblem is, I've got nothing of the sort on hand. These resort types may have what you need. We've been saving this recipe for a heavy hitter. Make sure Seahorn's alright before cooking it up, yeah?", progress = "Ngh. Did they get me with that Black Blood?", completion = "Limes? What's all this then? We're at war with far worse than scurvy!", objectives = "Collect Limes from the Resort Staff at the Blackwater Marina.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83200] = { id = 83200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Vast, Ye Swabs", description = "Urgh. I've been locked up for so long. In my anger, I got reckless.\n\nWhatever Noggenfogger gave ya, I promise not to squander. Get me back in the fight and we'll bring the full swell of Blackwater's might down on these invaders.", completion = "I'm feeling brand new, thanks to you.\n\nThey've transformed our marina into an overpriced resort in the front with a Black Blood smuggling operation in the back. \n\nLet's get even.", objectives = "Brew the Noggenfogger Deluxe with Lime and feed it to Fleet Master Seahorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83201] = { id = 83201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expedited Delivery", description = "Blackwater can take the marina from here. But the people aren't safe with Black Blood that's already out there.\n\nThose flying transports must be taking the Black Blood somewhere under Venture Co. control. Commandeer one, and you might find Grimla. She was headed in that direction when we split up, shouting that a friend of hers was on the way.", completion = "Just the two people I wanted to see. We're up to our eyes in Black Blood over here.", objectives = "Hitch a ride on a Malfunctioning Cratemover.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83202] = { id = 83202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Punching Up", description = "The time for talking out our differences is over. I'm done second-guessing who is still standing with Gallywix.\n\nSome of Nikki's people are keeping these new weapons in production. So, we take them out. It makes cleaning up Venture Co. after all this is done way simpler too. \n\nJust be careful. Nikki won't stick her neck out for her lieutenants, but she'll take the chance to rig a fight against you.", completion = "Had to be done. We're not finished yet.", objectives = "Defeat the three Venture Co. loyalist lieutenants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83203] = { id = 83203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons Hot", description = "The destructive impulses of those who harvest Azeroth for their own profit never cease to horrify me. But these weapons are like nothing that has come before.\n\nAll containers of Black Blood must be overturned and destroyed. Weapons fueled by it crushed and dismantled. Those who wield it against others, put down. The people of this city, and this world, won't be safe until we do.", completion = "You've done well. But now, we must strike at the heart of where their weapons are assembled.", objectives = "Destroy Black Blood crates and weapons in the Heaps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83204] = { id = 83204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thingamajig", description = "Nikki's tech is powered by Black Blood. I know that because I worked on half of it. That also means I have an idea on how we might knock her out of the sky for long enough to take her out. \n\nNo time for pre-production. We gotta build.\n\nRemember our flashy little hoverboard adventure? Ice is nice, eh? I'm thinkin' of a similar principle--the trash heap oughta have all the salvage we'll need to build this hypothetical thingamajig.", progress = "You got time to yap, then you've got time to smash!", completion = "There's only one engineer I know who'll have the smarts to build what we need in time to take down Nikki...", objectives = "Recover parts for Pamsy in the Heaps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83205] = { id = 83205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Production Halted", description = "<Orweyna rubs her palms with dirt, then cracks her knuckles.>\n\nNow, we teach those who toy with Black Blood nature's wrath. I am eager to call upon the roots twisting through Azeroth.\n\nJoin me. Unleash nature's fury as we did before. Let us destroy their prized stockpiles of Black Blood.", progress = "I would not have guessed Orweyna was that much of a natural at dodging rockets.", completion = "Of course the spill became a giant monster. Well, at least you dealt with it. The less Black Blood they've got to fuel their weapons with, the better.", objectives = "Destroy the Black Blood stockpiles in the Heaps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83206] = { id = 83206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Own the Streets", description = "The trade princes ain't exactly been fair to the goblins here, so this can't be just another cartel war. The crowd needs to know they ain't fighting for Bilgewater or Steamwheedle. \n\nThey're fightin' for Undermine. \n\nWe need someone who ain't a cartel big shot to help rile 'em up and keep 'em safe. Do whatever it takes to get them to the Gallagio and show these goblins this is their city.", completion = "Gallywix doesn't own these streets. We do. After this, he'll never forget it.", objectives = "Rally the people of Undermine against Gallywix.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83207] = { id = 83207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Top Gal", description = "We've got Gallywix backed against the wall. Seeing Undermine and its people he's kept under his thumb finally rising up.\n\nHe thinks this \"Fixer\" of his will keep him safe. Let's show Gallywix, Nikki, and everyone else that things are different this time.\n\n<Gazlowe looks over the thingamajig he's just finished jury-rigging.>\n\nWatch this.", completion = "Take it all in. We won. Gallywix can squirm away for now, but we took our city from him. \n\nToday, Undermine belongs to us.", objectives = "Defeat Nikki the Fixer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83229] = { id = 83229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: When the Deeps Stir" }
quests[83240] = { id = 83240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Theater Troupe", description = "Since you're an honorary member of the theater troupe, {name}, what do you think about playing a part in our plays?\n\nNo big parts--I don't want to upset the rest of the troupe by taking away their limelight. You know how they are.\n\nAre you available, say, once a week?", progress = "The show must go on! And on. And on. We've been renewed for a permanent showing. For the earthen that means... well, it means we're all employed for a long time.", completion = "Marbleous! You're the perfect addition to our theater troupe, {name}.\n\nPlease come and help us again in our next showing!", objectives = "Participate in the Theater Troupe event.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83247] = { id = 83247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suspicious Minds", description = "For many years, the only non-Arathi we ever saw in Hallowfall were trying to kill us. Nerubians, shadow creatures, beasts. So, forgive me if I view your sudden arrival with suspicion.\n\nHowever, my better half would urge me to be more welcoming... and I want to try to be better. For her.\n\nSome of the salamanthers in Rumshackle have been bothering us. Kill them and bring me proof.", progress = "Others may be satisfied with just your word that you have done what I'd ask. \n\nI am not.", completion = "You have helped.\n\nPerhaps she is right, and perhaps I should follow the example set by Dunelle.\n\nThank you.", objectives = "Find 9 Salamanther Hearts in Rumshackle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83271] = { id = 83271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There's Always Another Secret", description = "After me da' did whatever he did, the titans' machines are back online--even the ones here in Dornogal.\n\nDagran was havin' enough fun with Brinthe askin' her a thousand questions, but now he's helpin' her sort through the Archive.\n\nAn' now he wants your help. He was too excited to tell me why, but he wanted ye to meet him in the Archive.", completion = "Fascinating. This is clearly a chamber meant for a Keeper. But for what? \n\nWe need to investigate.", objectives = "Check in on Dagran Thaurissan II and Brinthe in the Archive in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83274] = { id = 83274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Original Path Through Time", description = "Old warriors keep spinning tales about how things were so much tougher around Azeroth back in their day.\n\nI bet they would say you're not tough enough to last 10 minutes in their world.\n\nThink you're tough enough to find out? How 'bout you show me.", progress = "You're not givin' up, are ya?", completion = "You did it, {name}! Way to show those old warriors that Azeroth is still in good hands!", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83275] = { id = 83275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gear Enchanting", description = "Hello, outlander!\n\nI've heard of your exploits since your dramatic arrival on our shores. We earthen welcome your aid.\n\nI can teach you how to enchant your gear with resources from my land. To defeat our enemies, every bit of power helps.", progress = "The enchantment and ring I gave you are fitting for each other.", completion = "May you be undefeatable as the earth itself. On your way now, outlander!", objectives = "Complete the item enchantment tutorial by enchanting any ring using the enchantment given from Ellerdin, Enchant Ring - Glimmering Haste.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83276] = { id = 83276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Private Spindle", description = "One of my weave-rats has failed to check in for an unusually long time. I sent Spindle to retrieve information we could use against one of Ansurek's favored wretches, but she has not returned from her assignment.\n\nMeesk the Venomtongue is a wretch and a sycophant, but he is dangerous all the same. While I have much trust in my dear Spindle's abilities, I fear what a malefactor such as Meesk would do to one of my little ones should he find them.\n\nFind Spindle. Make sure she is well.", progress = "<All of Spindle's eyes widen with both relief and embarrassment at the sight of you.>", completion = "<The little spider looks at you with many pleading eyes. You get the sense that she does not want you to speak of this to anyone.>", objectives = "Find Spindle in the High Hollows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83277] = { id = 83277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Personal Pilfering", description = "<The little spider looks around the room, each of her eyes narrowing.\n\nYou recall The Weaver telling you to retrieve evidence to blackmail Meesk.\n\nBut it appears as though ransacking Meesk's storage is now personal for Spindle.>", progress = "Well, my morsel? Did you find anything of note?", completion = "I see you've returned my Spindle to me. And some rather interesting bits of evidence, to boot.\n\nIt seems that varlet Meesk has leveraged a willingness to slander his betters in order to gain the favor of Ansurek and her ilk. Not only is his power growing by the day, but it does so at the expense of Queen Neferess' legacy.\n\nWell, that simply will not stand. Return to me soon, my little morsel. I need some time to concoct our next course of action.", objectives = "Find 3 pieces of Incriminating Evidence in Meesk's Retreat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83278] = { id = 83278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hillhelm Family: A Lost Shoe", description = "<A shoe in the style worn by members of the Hillhelm family.  Maybe Aliya Hillhelm can shed some light on it.>", completion = "Addysen and I used to tiptoe barefoot through those caves. With light steps, the slumbering fungus would not awake. It wasn't foolproof, and we did lose a lot of shoes escaping from angry Lashrooms.  \n\nThis shoe, however, seems to have once belonged to Gerta?", objectives = "Deliver The Lost Shoe to Aliya Hillhelm at Hillhelm Stead.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83279] = { id = 83279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prove One's Mettle", description = "Yes, you helped us out with these pests, but it is not enough. I need more.\n\nOne of the areas near our town has been overrun by shadow. If you are truly not being controlled by your... strange background, you would have no problem destroying the source of this danger, would you?", completion = "I have been following the Church of the Sacred Flame since the moment I was born. Doctrine is hard to set aside.\n\nBut I see now that you are here to help. And as long as you use your powers for us, I will reach out a hand of friendship--regardless of where that power came from.", objectives = "Defeat the Coalesced Iniquity in Rumshackle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83282] = { id = 83282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hillhelm Family: A Clutch of Eggs", description = "<A clutch of chicken eggs, they must have come from a nearby farm.  Maybe Aliya Hillhelm can shed some light on it.>", completion = "You stumbled upon this in the nearby caves? We have a few adventurous chickens who likely wandered in there.\n\nTracking down all the runaways can be a full-time endeavor.", objectives = "Deliver The Clutch of Eggs to Aliya Hillhelm at Hillhelm Stead.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83283] = { id = 83283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Morale", description = "Please excuse my husband's rudeness. When we signed up for our expedition, we expected to be away from our families for a few years at worst. Instead, we settled here as we guard against--well, against the end, against Renilash. Who knows when our watch will end?\n\nI've been stockpiling a cache of wine from our church vineyards to share with everyone when tensions got high. My hiding place, Rumshackle, has been overrun by creatures. Can you get the wine for me?", progress = "Imagine twenty Arathi huddling under the safety of a single light for ten years. Imagine they're waiting for a chance to let their hair down with a good drink with their comrades.\n\nNow imagine how they'll feel once they hear the wine is gone.\n\n...please hurry.", completion = "Oh, thank the Flame.\n\nYou've prevented a small riot from forming. Bless you, bless you, bless you!", objectives = "Retrieve 6 barrels of Imperial Brut from Rumshackle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83285] = { id = 83285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ancient Scroll", description = "A haze seems to obscure the details of the scroll at first. As you concentrate on making out the scroll's features, the haze briefly dissipates revealing a pristine scroll made of the finest vellum, with a seal that looks so fresh the wax doesn't even seem set yet. In a blink, the scroll feels dangerously brittle, and the seal so delicate it could crack at any moment. As the haze begins to form again, you see the scroll shimmer through all possible points between these two extremes.", objectives = "Scrolls are fascinating items. They travel far and wide across the lands, yet this one seems to also travel through time.\n\nThe fact that you found this scroll where you did is both an omen and a blessing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83286] = { id = 83286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Hidden Beneath Dornogal", description = "Strange. The mechanism and console here is receiving power, but I cannot initialize the reboot sequence.\n\nDagran's query may have to wait.\n\nI have been able to ascertain the facility's designation: the \"Vault of Memory.\" This leads me to believe that my original theory was correct. It is connected to the Archive in Dornogal.\n\nPerhaps, since both of you are familiar with this type of titan installation, you may have a better chance bringing it fully online.", progress = "Take your time. It has been here for millennia. I am sure it is not going anywhere.", completion = "I now have access to the mainframe here in the Vault of Memory. \n\nThere is a lot here but... it is fragmented. It will take time to recompile it.\n\nAnd some data, I'm afraid, may be damaged and need repair.", objectives = "Restart the central mainframe in the Vault of Memory in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83306] = { id = 83306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where the Wild Things Camp", description = "Some of my people found a few haranir setting up one of their camps to the southwest. They were missing some vital supplies, so my people offered to help out. However, I worry about how they're all getting along over there.\n\nCould you check in on them? Make sure we're being good hosts to the haranir... and that nobody has inadvertently offended anyone. Please.", completion = "You again. Curious.", objectives = "Meet Orweyna at Wildcamp Ul'ar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83315] = { id = 83315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparing for the Unknown", description = "This will be a long process. Longer, I fear, than Dagran can stay here in the Isles.\n\nBut perhaps... \n\nThere are many titan relics I can use as \"keys\" to unlocking information in the mainframe or to repair it. That may make the process go more quickly.\n\nOnly time will tell.\n\nYou have helped us enough, {name}. Go back to Moira and tell her what we have discovered.", completion = "Well, I know where to find Dagran if I'm missin' him.\n\nIt's good tae see him so happy an' in his element. He's done me proud.\n\nThank ye for helpin' him along the way.", objectives = "Return to Moira Thaurissan in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83321] = { id = 83321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Bats", description = "Hey. Her ladyship has a lead on some really strange bat that was flying around the Wormlands. \n\nThe spies reported it behaving more like a person than a bat. We think we might have a druid out there, but it ain't revealin' itself to the nerubians on purpose.\n\nYou have one of those faces that make people hesitate before punching. Head out there and take a look.", completion = "You! You are just what I need.", objectives = "Investigate a possible druid sighting.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83322] = { id = 83322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dawnbreaker: The Christening", description = "The flagship of the Arathi armada is the Dawnbreaker. She is a marvel of Arathi engineering and faith in the Sacred Flame. Her presence in the Hallowfall sky will help us push back the nerubians when next they dare launch another assault on our lands.\n\nAs someone who has helped us so much in the past, you are cordially invited to the christening ceremony of the Dawnbreaker. If you could make sure it goes off without a hitch, you will have my personal gratitude.", progress = "The Dawnbreaker will cause problems for the nerubians once she is active. It is very important everything goes off without a hitch.", completion = "Well.\n\nThat went as well as could be expected for a ceremony in Hallowfall.\n\nThank you for being here.", objectives = "Help the christening ceremony in the Dawnbreaker dungeon succeed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83324] = { id = 83324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Silken Thread", description = "You looking for work or something? <Linny squints her eyes at you.> If you're just hanging around I've heard some whispers from the capital. An associate of the Weaver is looking into some business in the Silken Ward.\n\nThe new ward is supposed to be a fresh start for citizens of the capital but the Queen's Pale Weavelashers have been treating it like a military camp. This isn't sittin' well with the populace.\n\nMeet with a nerubian named Sum'latha outside the ward. She can fill you in on the details.", completion = "You must be the help our \"mutual friend\" sent. Welcome to the Silken Ward.", objectives = "Meet with Sum'latha at the Silken Ward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83325] = { id = 83325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bountiful Beetles", description = "General Anub'azal has great plans in motion for the swarmery, Rak-Ush. He intends to return it to working order, to support his war campaign.\n\nHowever... I have my reservations about the two he left in charge. \n\nKish'nal seems to have a good head on his shoulders, but Vix'aron? Volatile is an understatement. They may require some... prodding.\n\nSeek out Kish'nal at Rak-Ush and follow up on Anub'azal's orders.", completion = "Ah, so the general has sent out an observer?", objectives = "Speak with Kish'nal in Rak-Ush.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83326] = { id = 83326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Candle", description = "You are good candle-taker. \n\nWe have one last job for you, your waxiness! One more job! Then no more sticky business. \n\nBIG candle in basement. Stone-ones use it to keep rats away from their honey juice. We no rats! We kobo--ooolds. \n\n<There's an awkward pause.>\n\nNothing rhymes with kobolds, hm. \n\nGet us big candle!", progress = "Candles! Candles! Candles!", completion = "Whoop! Whoop! The candle! The BIG one! \n\n... you smell smoke?", objectives = "Steal the final candle for the suspicious vent in the Gundargaz Inn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83328] = { id = 83328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Analysis Interface", description = "This is the Analysis Interface. \n\nIn order to ensure our primary programming remained intact, these consoles were installed with a series of inquiries to assess the memory matrix of the newly awakened. \n\nAlthough Dawn will encourage you to answer in any way that you please--I... well, I hope you'll answer truthfully.\n\nProceed when ready.", completion = "Who you were, who you are and who do you want to be? \n\nAll questions every {race} from now on will be allowed to ask.\n\nOur fate and our purpose is ours to choose.", objectives = "Complete the Analyzing Sequence in the Analysis Interface.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83329] = { id = 83329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Level 50" }
quests[83330] = { id = 83330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Level 60" }
quests[83331] = { id = 83331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserve and Pretend", description = "Chive dig for history. You help find? \n\nGot history detector from goblin. Said it finds history underground! You use. Chive dig.", completion = "Many thanks, dig-finder. \n\nChive know these have no important history... but they will one day.\n \nChive will keep safe until then. Kobolds make new history. \n\nThen save and protect. Forever.", objectives = "Help find places to dig for \"historical objects\" by using the goblin \"history detector\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83333] = { id = 83333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gearing Up for Trouble", description = "Greetings friend,\n\nThe machine is once again in disrepair and requires restoration. \nI am in need of your expertise to successfully perform maintenance.\n\nA reward shall be provided for well-executed assistance.", progress = "Status report?", completion = "The machine continues in its duties once again.\n\nThank you again for your assistance.", objectives = "Complete 20 waves of the Awakening the Machine event.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83334] = { id = 83334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wealth of an Empire", objectives = "The Arathi truly appreciate all your help in this dangerous land. Please accept this symbol of our gratitude.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83335] = { id = 83335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Boroughbreaker", description = "<This note is nailed into the post with a small chitinous plate.>\n\nFor crimes impeding the Edicts of Dornogal, the Council has deemed a reward be yielded to any who slays the chitinous beast known as Stik'kar.\n\nA sample of Stik'kar's armor is attached. If you are unable to damage it, you are urged to carry on in your duties and leave this task for another.", completion = "The Council can bicker all they want. The true heroes are those that go out and make the world a safer place. Thank you hero.", objectives = "Slay Boroughbreaker Stik'kar in the Isle of Dorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83336] = { id = 83336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Earthwound", description = "<Etterca grumbles as you approach.>\n\nGround is shaking. 'Tis no good.\n\nTroubles are awakening the elements again. Stirs rot in them. Danger to us all. Bring them to heel and give its heart here.\n\nOnly then the earth can begin to heal. Only then can Etterca do her duties.", progress = "<Etterca grumbles and stares at you blankly.>", completion = "Hmmph. Broken heart takes long time to mend. \n\nEtterca hears you, Roth. Earth will mend.", objectives = "Acquire the Broken Stoneheart from Roth the Earthwound in the Isle of Dorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83337] = { id = 83337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormscarred", description = "Take a look around this beautiful town. What do you see? Ranchers 'n' their mosswools. But where  is this rancher's flock? In the guts of a beast, they are. Stormscar they call 'im. \n\nStormscar, whose howl is as the thunder. Whose bite is lightning. Whose belly is full of my life's work. \n\nI came here to buy weapons and all we have is ranching equipment. You look strong. Would you put an end to Stormscar's reign in our pastures?", progress = "Have you done it yet?", completion = "Thank you, adventurer. My role in this world is to be a rancher. Yours is to slay wolves. We all have our places.", objectives = "Slay Stormscar in the pastures near Rambleshire in the Isle of Dorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83338] = { id = 83338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mage Slayer", description = "I confess I have come here with reason. There is one entity that may be out there still that cannot be allowed its freedom.\n\nA prisoner from the Violet Hold that we begrudgingly know as the Mage Slayer. I had come to request aid from these people, but they are farmers and ranchers. I hope you are better equipped for a challenge.\n\nSeek out this fiend and put an end to its existence.", completion = "Dalaran may be in ruins, but the Kirin Tor does not grant you release Mage Slayer!\n\nThank you for your assistance, {name}.\n\nAre you sure you defeated all of it?", objectives = "Slay Mage Slayer Phytethil near Rambleshire in the Isle of Dorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83339] = { id = 83339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spirebreaker", description = "We are no strangers to nerubian attacks. The Kirin Tor is well equipped to handle such a threat. Dalaran...\n\nWas equipped. I cannot fend off all of this town's foes, but you might be able to. I spotted an ambush near the road on the way here. An all too familiar tactic of an all too familiar foe. Go spring the trap and slay the  monster that lurks below.", progress = "Are they safe now?", completion = "Thank goodness. With your aid, we may be able to make a difference... this time. \n\nThese people deserve safety.", objectives = "Slay Anub'esska on the road near Rambleshire in the Isle of Dorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83345] = { id = 83345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Battle", description = "I have heard that your people wage massive battles against one another across huge fields and in crumbling ruins. \n\nSeems like a bit of a waste of time, fighting over flags when there's proper work to be done. However, the field of battle can test the mettle of a warrior. In that, there is value.\n\nBring me news of your victories! I am open to being impressed.", progress = "We Machine Speakers are no strangers to trial by fire. It is good for learning teamwork and testing out strategies.", completion = "You return with news of victories? Perhaps some losses?\n\nEvery loss is a lesson towards improvement. Celebrate your victories as well.", objectives = "Win 4 Battleground matches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83347] = { id = 83347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissary of War", description = "Are you up for a real challenge? Delve into the darkest places and soar to the highest heights while upping the challenge. \n\nBy pressing ourselves to the extreme we can truly test our skills.", progress = "By pressing ourselves to the extreme we can truly test our skills.", completion = "That was no easy task you completed. I am moderately impressed.", objectives = "Complete 4 dungeons on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83357] = { id = 83357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Very Best", description = "The bond between us and our machines is much like the one others have with their pets. You must be in harmony with your companions in order to accomplish great things!\n\nShow me that you can work as a team with your pets. Defeat your enemies with their assistance!", progress = "You must be in harmony with your companions in order to accomplish great things!", completion = "You and your pets are a tough team to beat!", objectives = "Defeat 5 players through Find Battle with a team of level 25 pets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83358] = { id = 83358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arena Calls", description = "Have you proven your mettle in the arena? Win enough battles, and we might even find your tales worthy of storage in the Archives one day.", progress = "Do not let your guard down in the arena!", completion = "Good job! You are on the right track with your training.", objectives = "Win 10 Arena Skirmish battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83359] = { id = 83359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shattered Path Through Time", description = "One of your people brought me a strange tale of the cataclysm that tore Azeroth apart. In your lands, this was felt most direly due to the machinations of the wicked creature Deathwing. \n\nTravel through space and time and engage with him and other threats.", progress = "Only the titans should reshape the world.", completion = "Echoes of the Cataclysm were felt throughout Azeroth. It was a dire time indeed.", objectives = "Defeat 5 Timewalking raid bosses or dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83360] = { id = 83360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fel Path Through Time", description = "I have heard tales of an entire Legion of threats that lurks along the paths of space and time. \n\nDefeat them and bring me back news of their demise.", progress = "Some of my people may see the arrival of the outlanders as an invasion, but I am glad it was you who landed on our shoes, and not the Burning Legion.", completion = "Have you snuffed out the Burning Legion? They deserve nothing less, from what I've heard.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83362] = { id = 83362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shrouded Path Through Time", description = "One of your people brought me tales of Pandaria! I would very much like to fly through those skies one day. \n\nWalk through mist and time and bring back news of your deeds.", progress = "I wonder what it is like to be covered in fur like a pandaren. I hear there are many floating places to visit in those lands. May they all stay afloat.", completion = "Ah, you return damp with mist-dew. I hear you bring news of your victories in Pandaria.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83363] = { id = 83363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Burning Path Through Time", description = "Your people have brought me tales of a Dark Portal wherein lie many enemies and challenges. I would like to hear more of these tales.\n\nTravel through time and space to this outlandish place, vanquish its foes, and bring me news of their demise.", progress = "Some of my people may see the arrival of the outlanders as an invasion, but I am glad it was you who landed on our shoes, and not the Burning Legion.", completion = "You return in glory and bring me tales of the quenching the fires of the Burning Legion?", objectives = "Defeat 5 Timewalking raid bosses or dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83364] = { id = 83364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Savage Path Through Time", description = "Ever since your city fell out of the sky, I have learned more of this world's history and the challenges that heroes like yourself have faced. \n\nLearning from the past is how we ensure our future. Walk through time to a past limed with hellfire to defeat those threats once more and bring those lessons forward.", completion = "You are returned and our reality has not unraveled itself, so I take it you were successful.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83365] = { id = 83365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Frozen Path Through Time", description = "Ever since your city fell out of the sky, I have learned more of this world's history and the challenges that heroes like yourself have faced. \n\nLearning from the past is how we ensure our future. Walk through time to the frozen past, defeat those threats once more, and bring those lessons forward.", progress = "Much has happened in the greater world while we worked in this place. I hear you had a hand in quite a bit of those tales.", completion = "What lessons do you bring from your journeys through time?", objectives = "Defeat 5 Timewalking raid bosses or dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83366] = { id = 83366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The World Awaits", description = "Perhaps we can turn your tragedy into a mutually beneficial experience for us both. There is much you can do to be of assistance to the earthen. \n\nLend a hand where you can.", progress = "My people face a wide range of difficulties these days, as do yours. We can make the best of what's befallen us both.", completion = "News has come to me of your deeds among my people. Your name is spoken by earthen far and wide.", objectives = "Complete 10 World Quests in Khaz Algar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83417] = { id = 83417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out-laws", description = "We're a traditional goblin family, an' my sweetie's intended's from one too. Young people start work on a contract, an' buy each other out when they get hitched so they can get time off.\n\nI've got the cash for my sweetie to buy her intended's contract out, but it would be... embarrassin' if her intended didn't have the moolah for my perfect peach's contract, ya know?\n\nGo talk to that kid and make sure he's set for the big day. And if he's not? Fix it.", progress = "Everything needs to be perfect for my girl's big day. Or else.", completion = "I figured something like that might happen. Good job.", objectives = "Talk to Vrizek and make sure he has the Contract Fee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83418] = { id = 83418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Coat", description = "My princess deserves only the very best Azeroth has to offer--and that goes double for her clothes. How else are people supposed'ta know how incredible I think she is?\n\nI got a guy who's hooked me up with an amazin' and rare pelt for my little girl to turn into a fabulous coat. Go meet the guy and bring back the goods. And you better not get anythin' on it.", progress = "Tick tock!", completion = "Hey, that looks swanky! My precious is gonna look amazin' in those feathers!", objectives = "Acquire the fabulously feathered coat material.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83419] = { id = 83419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Guest List", description = "The perfect weddin' has the perfect guest list!\n\nBut I'm still waiting on some RSVPs. Papa said he'd make sure they showed up, so that means you gotta remind them they'd love to come to my weddin'. It's gonna be the biggest bash this town has ever seen! Why wouldn't they want to come? We're family! Mostly.\n\nAnyway, get everyone on this list to agree to come to my weddin'. Remind them Papa said \"or else.\"", progress = "You talk to all my slacker relatives yet? I have to organize the tables.", completion = "Alright! I can finalize my table seating now.", objectives = "Get positive RSVPs from the remaining guests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83420] = { id = 83420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catering to Perfection", description = "My perfect day needs the perfect food! I've been looking at things on Gobstagram, and Chef Hardslice is my one and only choice for catering. Papa promised I'd have the best, and he's good to his word!\n\nI need you to make sure that everything on my menu makes it to the table for picture perfection. Everyone needs to see how fabulous my wedding is. \n\nAhh! I am so excited! I can't wait to see Chef Hardslice's creations on my table at my wedding!", progress = "Isn't Chef Hardslice a genius?", completion = "My food is going to be the envy of everyone!", objectives = "Speak with Chef Hardslice and obtain missing ingredients.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83421] = { id = 83421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Wedding", description = "I hired some goons to crash the wedding. Only the best weddings get crashed, right?\n\nBut, I don't want to lose my deposit on this here venue. So, I need you to stop my crashers from getting too crashy, ya know?", progress = "Stop those goons from doing too much damage, or I'll take my deposit outta your hide!", completion = "Hey! I'll get my deposit back. Good job.", objectives = "Stop the wedding crashers from doing too much damage to the venue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83432] = { id = 83432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rookery", description = "My contacts around Dornogal have told me to keep this a secret, but I trust you mainly because I need someone to do the job.\n\nWe have a problem within the Rookery's walls--a skardyn outbreak.\n\nI need someone to clear the Rookery of skardyn, find the source of the outbreak, and drop the boulder on it.\n\nOnce you complete the mission, come back to me for your reward.\n\nAnd remember... this stays between us.", progress = "Back so soon? Good news, I hope?", completion = "Well done. You are officially my favorite hero.\n\nAt least until tomorrow.", objectives = "Biergoth wants you to enter The Rookery and put an end to the skardyn threat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83436] = { id = 83436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cinderbrew Meadery", description = "Word has come from a contact of mine named Wenbrandt. You may have heard of him. He runs the Cinderbrew Meadery.\n\nHe says that goblins affiliated with an organization calling itself Venture Co. are trying to take over the meadery. We cannot have that. I need you to get into the meadery and remove that threat.\n\nCinderbrew is an earthen product and should be under earthen control. Wenbrandt will teach them this lesson--but until then, I will count on you to finish the job.", progress = "Any news are better than no news at all.\n\nDo not keep me waiting. Unlike the mountains, my patience is like that of a landslide.", completion = "Wenbrandt sent me the word. Well done. \n\nHere is your reward.", objectives = "Biergoth wants you to remove the Venture Co. from the Cinderbrew Meadery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83442] = { id = 83442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tossed and Torqued", description = "All my notes. My plans!\n\n<Snap is shaking with anger.>\n\nI just know it was Mite Sparkcog who tossed my apartment. He's my work rival and probably wanted my newest invention for himself--the Smellersweller 5000!\n\nIt's an attachment for the grills we design. I'd just finished the schematic for our boss when I stepped out for some grub. By the time I got back...\n\nMaybe he didn't find it. Help me look first, then we can deal with Mite.", progress = "The schematic is of a muffler-type part that sticks onto a grill. It's so amazin' that you can't miss it!", completion = "<Snap crumples up the taunting note.>\n\nOh, he is not gonna steal my promotion this time!", objectives = "Search Snap Vellumgrease's apartment for the schematic in Undermine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83443] = { id = 83443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkflame Cleft", description = "A new ally of ours, a kobold from the Ringing Deeps named Skitter, has contacted me.\n\nI need you to go to Darkflame Cleft and remove a certain threat--something that Skitter called The Darkness.\n\nHow can a kobold be afraid of the darkness when they spend most of their time underground? It makes no sense to me. But kobolds will be kobolds, and I will not busy myself with understanding.", progress = "Let me know if you figure out what this darkness is all about.", completion = "So The Darkness is a kobold entity? And here I thought Skitter was over-exaggerating.\n\nHere is your reward.", objectives = "Biergoth wants you to venture into Darkflame Cleft and face The Darkness.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83445] = { id = 83445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Smells", description = "Ooh! That Mite makes me so mad! He even took credit for it. An' I was right. He's going to present the Smellersweller to our boss!\n\nIn fact, he's probably presenting it right now!\n\nThat gives me an idea though. We may not have the schematic, but Mite won't know how to operate it. If we can show the boss it's not Mite's design, maybe I'll still get credit!\n\nHow good are you at pressing buttons? Will you help me present the prototype?", progress = "We've got to hurry! Mite's had most of an hour to prepare.\n\nAll while I was on a break, that mook!", completion = "That no-good, brainless, fried worm of an engineer!\n\nHe'll pay for this!", objectives = "Speak with Snap Vellumgrease at Cheap Grillz in Hovel Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83446] = { id = 83446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cease and Desist", description = "Our presentation showed that we were the ones that could actually operate the device! If Sammy weren't so focused on the documentation bein' in Mite's hands... Anyone else could clearly see we had made the thing even if we didn't have the schematics!\n\nBut this ain't over. You saw how Mite overloaded the Smellersweller? We can do that too! Punch a bunch of buttons all at once and we can exploit his half-baked, all-stolen idea!\n\nWe go in, we mess up the prototype, an' we set production back months!", progress = "Mite... might actually have a good point there.", completion = "Oh, uh. Hi, {name}. Thanks for tearing apart those busted prototypes for us. Here's your cut.\n\nAs it turns out, this was all a misunderstandin'. He broke in 'cause he thought I had stolen HIS idea.\n\nAn' actually he has had a good idea for the Smellersweller... Smellifier... whatever.", objectives = "Stop the Smellersweller 5000 production at Cheap Grillz in Hovel Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83457] = { id = 83457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stonevault", description = "I have a job for you from High Speaker Brinthe herself.\n\nThe skardyn corruption is taking over the Stonevault. To contain the panic, High Speaker Brinthe has asked us for help. I told her she could trust us like we trust the bedrock under our feet.\n\nGo to The Stonevault and remove the skardyn corruption. Let me know when the job is done.", progress = "Any news I can report to High Speaker Brinthe?", completion = "You are indeed like a bedrock--solid and trustworthy.\n\nI will let High Speaker Brinthe know of your success.", objectives = "Biergoth wants you to end the skardyn corruption within The Stonevault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83458] = { id = 83458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priory of the Sacred Flame", description = "Good to see you, {name}. I have a job just for you.\n\nSister Etna Blayze of the Arathi is convinced that something is wrong within the Sacred Flame Priory. She did not expand on the matter at hand.\n\nPlease head out to the Priory of the Sacred Flame and join the sister. A stomach pebble tells me she might be right and will need your help.", progress = "I am not sure if you are still here or already back.", completion = "Sometimes a stomach pebble is all you need to listen to.\n\nHere, a reward for your time and effort.", objectives = "Biergoth wants you to go to the Priory of the Sacred Flame and help Sister Etna Blayze.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83459] = { id = 83459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dawnbreaker", description = "I have received word from General Steelstrike of the Arathi. She asked for you to attend a ceremony aboard The Dawnbreaker.\n\nBy attending, she means she needs an extra pair of eyes--maybe two or five. Have you ever secured a ceremony before? It feels like a puddle of sticky mud down in the Forgegrounds.\n\nI'm sorry, but General Steelstrike asked, and I replied with a simple \"yes.\" As the saying goes, not every hill is going to be exciting.", progress = "I know ceremonies are not your cup of cinderbrew. They are not mine either, but our job is important.", completion = "I received word that the ceremony was more of a mudslide than a sticky mud puddle.\n\nI am happy that you were there.", objectives = "Biergoth wants you to go to The Dawnbreaker and help General Steelstrike with securing the ceremony.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83465] = { id = 83465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ara-Kara, City of Echoes", description = "Tulumun, an agent of a new contact known as the Vizier, has approached us.\n\nI never expected a nerubian to come to us for help, but what they brought to our attention could threaten us all.\n\nI will need you to descend into Azj-Kahet and infiltrate Ara-Kara, the City of Echoes. If what Tulumun told me is true, we cannot let whatever they have woven down there escape.\n\nPut an end to their operation. Bring back evidence of what you find.", progress = "Move quickly. Their operation cannot be allowed to come to fruition.", completion = "Black blood? I am unsure what that is, but if a nerubian calls it vile, I will take their word for it.\n\nHere, take this for your trouble.", objectives = "Biergoth wants you to stop the operation taking place within Ara-Kara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83469] = { id = 83469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "City of Threads", description = "Tulumun, our Nerubian ally, contacted us once again. He spoke of a place called the Transformatory where horrific experiments take place.\n\nI will need you to infiltrate the city and then rendezvous with the Vizier himself for the rest of the mission. \n\nEliminate the Vizier's enemies, end the threat, and return to me for your payment.", progress = "Make it quick. I do not wish for you to spend more time than you have to in a nerubian city.", completion = "I do not know if I trust these nerubians--not yet.\n\nTheir capability to devise sinister ploys, and these facilities to support their darkest plans... It leaves a rock at my core.", objectives = "Biergoth wants you to eliminate all threats within the City of Threads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83484] = { id = 83484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, Rats!", description = "Okay, scout's honor this ain't a joke. I need help because... \n\nI turned my best friend into a rat.\n\nMy friend Allie is the cook here. She tries her best but she's... no good. She's got a bum sniffer. So, I bought her a potion that would make her smell better!\n\n...I mean, improve her sense of smell. But it turned her into a rat! Then she ran off!\n\nYa gotta find her for me. Dealer had another potion to understand rats. I'm too afraid to drink it though.\n\nCan you use it an' find her?", progress = "The rat tilts its head, observing you closely.", completion = "I can't just be a rat forever. I need your help!", objectives = "Find Alice Grillspark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83485] = { id = 83485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Potent Potables", description = "<sniff> <sniff>\n\nThis potion has the scent of the Vatworks on it. There's a vendor at the northern edge there who sells potions. It must be from him. If you can find him, maybe you can get him to hand over an antidote.\n\nPlease help. You're the only one who can understand me!", completion = "If you're reading this, I'm out scavenging for reagents along the Kaja'Coast. \n\nIf you're here to collect on a debt, you are TRESPASSING and must disregard this note.\n\n-Getry", objectives = "Help Alice Grillspark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83486] = { id = 83486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remote Work", description = "If you're reading this, I'm out scavenging for reagents along the Kaja'Coast. \n\nIf you're here to collect on a debt, you are TRESPASSING and must disregard this note.\n\n-Getry", progress = "The pack has largely escaped damage. A well-worn book is visible from underneath the open flap.", completion = "<There must be Redberries growing somewhere in the area.>", objectives = "Locate Getry Sellswill at the Kaja'Coast in Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83487] = { id = 83487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Occupational Hazard", description = "<You surmise that collecting enough redberries and returning them to Humphrey should allow Alice to turn back into her usual goblin self.>", progress = "Any luck with that antidote, {name}?", completion = "Thanks again for the antidote. We'll hang onto it for later.\n\nTurns out Alice is a much better cook than she ever was before and wants to keep this success story rolling!", objectives = "Collect the redberry reagents and return to Humphrey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83489] = { id = 83489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering All Gladiators!", description = "Come one, come all, straight to Dornogal!\n\nIn addition to the usual selection of powerful equipment offered at the Contender's Gate, aspiring combatants and proven gladiators can purchase heraldry tokens which can be used to craft equipment certified for use in arenas and battlegrounds!\n\nPresent this brochure to Hotharn to receive a few of these, on us!\n\n- Aisha", completion = "Ah, I was beginning to wonder when the eager fighters were going to show up. \n\nHere you go, as promised. Use these when submitting Crafting Orders or when crafting your own equipment. The result will be just as powerful as what Lalandi sells over there, but these are great when you're looking for something customized to your liking. If you need more, you know where to find me.\n\nQuestions? Take them to the Forgegrounds.", objectives = "Deliver the advertisement to Hotharn at the Contender's Gate in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83492] = { id = 83492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warbands: Warbanding Together", description = "{name}, some adventurers have gotten together to form a warband and could use your help.\n\nFind Blue and her group in Gadgetzan.", completion = "Thanks for coming, {name}!", objectives = "Meet Blue and her Warband in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83493] = { id = 83493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warbands: Rift Reader", description = "I bet you're wondering what we're working on, huh? We're going to make our Warband Bank accessible from anywhere!\n\nRivet's calling it a Warband Bank Distance Inhibitor until I can think of something more fun, but we need a little help to get it over the finish line.\n\nIf we're going to make sure we can access our shared stash from multiple locations, we're going to need portals! And we tracked some doozies down out here.\n\nIf you could get us some scans of the local anomalies, it'd be a big help!", progress = "Did you find them?", completion = "Now that's some sparkly data!", objectives = "Scan Transpositional Anomalies near Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83494] = { id = 83494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warbands: Space Ghosts by the Coast", description = "There are an awful lot of half-teleported things wandering around the desert not too far from here. Really, any at all would be a surprising amount, but there are a bunch of them for some reason!\n\nThey don't seem particularly nice, but I bet we could learn from their predicament to ensure the Warband Bank Distance Inhibitor doesn't teleport our sweet loot into a tree!\n\nSee if you can find anything that might help us figure out what went wrong. It's not like people randomly teleport around, right?", progress = "Any clues?", completion = "Great job, {name}! I'm not sure what that is, but I bet it'll help!", objectives = "Collect Spatial Residue from the Partially Teleported creatures near Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83495] = { id = 83495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warbands: Twinsposition", description = "We're on a roll! We picked up an even more anomalous anomaly while you were out and tracked it down to just west of town.\n\nWe've got a brand-new Transpositional Signal Recombobulatron already set up out there, but I didn't want to start without you. You've been a big help, after all.\n\nAll you have to do is dial it in and throw the switch! Easy as pie, which I'm told is very easy.\n\nRivet says that the odds of something cataclysmic happening are pretty good, so I know nothing bad can happen!", progress = "Throw the switch!", completion = "Nice job!\n\nNot what I was expecting, but I have to say evil me was rocking that mustache!", objectives = "Activate the Transpositional Signal Recombobulatron outside Gadgetzan and deal with the consequences.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83496] = { id = 83496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warbands: Spacetime is Money", description = "Now that we've got all the transpositional data we could ever hope for, all we need to do is set up a wormhole in a suitable banking establishment and we'll be dropping gear into each other's pockets from the field in no time!\n\nAnd there just happens to be a bank right here in Gadgetzan!\n\nYou can even attune your own portal at the same time so you can access your own Warband Bank from anywhere. It's going to be so convenient!", progress = "Did you find the bank?", completion = "A few hiccups, but nothing some good old-fashioned teamwork wasn't up to! Go us!", objectives = "Place the De-Recombobulatron Matrix in the Gadgetzan Bank.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83497] = { id = 83497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Concerned Friend", description = "Ah, {name}, there you are! Great Kyron was asking after you and your friend Anduin. \n\nI think they want to talk to you about Faerin. Nothing urgent mind you, she probably just needs some good company. But we're all a bit worried about her.\n\nCheck in with Kyron when you have a moment, will you?", completion = "I hope the journey wasn't long.", objectives = "Meet Great Kyron in Mereldar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83499] = { id = 83499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Wasteland", description = "Kirin Tor survivors have been hesitant to return to this area. A great deal of energy was dispelled before and after Dalaran's crash. An invisible yet tangible miasma lingers in the area for those who are sensitive to it.\n\nIt is unclear if the site is hazardous or if other more corporeal dangers still lurk here.\n\nI can protect us, but I expended all my reagents at the Proscenium. Will you aid me in procuring more?", progress = "The last few days have been... difficult.", completion = "Yes, these will do. Thank you, {name}.\n\nDespite the shards and elementals roaming there, it seems the ruins are not immediately dangerous. But, if we are to spend any time here, an arcane barrier is wise.\n\nWe don't know the long-term effects of exposure of this kind.", objectives = "Help Aethas Sunreaver gather reagents required for a protective spell in the Tranquil Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83500] = { id = 83500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zekvir, Hand of the Harbinger", description = "We'll have tae watch out for Zekvir as we go exploring into delves. I don't think we're strong enough tae take him on just yet, but we will be!\n\nLet's keep explorin' and gettin' treasure until we're tough enough tae track down his lair and defeat him.", completion = "We did it! We made this place safe for all adventurers. \n\nThis should put Xal'atath in a tough spot, now that she's missing one of her most powerful toadies.", objectives = "Defeat Zekvir, the Hand of the Harbinger within his own delve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83502] = { id = 83502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lessons in Defensive Magic", description = "The spell for the barrier is ready, but I must channel it and define its perimeter. \n\nWhile I channel the spell, take these wards and place them at the edges of our would-be barrier.\n\nWe will empower the spell when you are finished.", completion = "<Aethas inhales.> \n\nYes. This will do... for now.", objectives = "Help Aethas Sunreaver cast a spell to create a protective arcane dome in the Tranquil Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83503] = { id = 83503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Dornogal", description = "The battle is finally over and I suppose it's time we lick our wounds. \n\nHead back to Dornogal, Champion. \n\nI'll be right there as soon as Khadgar is healthy enough to withstand travel.", completion = "Our battle has been hard fought. But there is still much to come.", objectives = "Return to Dornogal in the Isle of Dorn and report what happened.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83519] = { id = 83519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "But What About the Casino?", description = "Times are a changing. Now that ol' Jastor is kaput, the cartel heads are chomping at the bit to settle the fate of Undermine's crown jewel: the Gallagio.\n\nThere's a court proceeding tomorrow to make a final determination, but luckily the deed is squarely in the hands of someone I trust. \n\nTheir name: Rosebud Gallywix.\n\nI know. I know. But Rosey is a good egg. I'll introduce you to him later on.\n\nFirst, do me a favor. Ask the power players here at the party how they feel about the new owner.", progress = "Don't get turned off by the Gallywix name. He had a big family, and they ain't all evil crankshafts.", completion = "This... is bad.", objectives = "Ask about Rosebud Gallywix at the Gallagio's opening party.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83521] = { id = 83521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Little Help, Please?", description = "So, uh, I swear this never happens, but this kind fellow here pulled me over for a busted tail light.\n\nI just got that fixed. I swear it!\n\nWould you do me a favor? Keep him and any of his colleagues entertained. My license is in one of these compartments somewhere, I just gotta find it.\n\nShouldn't be more than a minute. Two at most!", objectives = "Deal with the Venture Co. \"Policers\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83522] = { id = 83522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Debting For A Living", description = "First of Rosebud's Chiefs on our list are the genius gaming duo: Kayjay and Fantastic Davey.\n\nNow, I heard from my wife's brother that Venture Co. bought up all the debt those boys got. Happened the minute Rosebud was done in.\n\nDid they murder him? Not a great motive if their debt was sky high, but you never know whose pocket a goblin is in either. \n\nBest we see how comfortable they are here at the ol' Venturewood landfill. If they don't want to sign the new deed, we might have our culprits!", progress = "You'll find all those in my employ are quite content. I've got the bills from various corporate training seminars to prove it.", completion = "You see? They're happy as Zandalari crustaceans.\n\nBut if you're truly invested in poaching their services, perhaps we can make a deal...", objectives = "Speak with Kayjay and Fantastic Davey about signing the new Gallagio deed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83524] = { id = 83524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gold In Them There Trash", description = "Kayjay and Davey are indeed masters of creating games. They've created a new one for me that's been an absolute hit.\n\nIf you're willing to accept the risk, then I will give you the chance to win their employment, and debt, from me.\n\nGrab a pickaxe, and enter the landfill. When the whistle blows, you'll compete against all my other \"employees.\"\n\nWin by the final bell, and I'll let these two go. Lose, and I'll own you.\n\nIt's called Slot Mining. And it will indebt you to me for life.", progress = "<Tarbonara says nothing. He simply snarls through his shiny teeth.>", completion = "You didn't win. Surprise, I guess.\n\nWelcome to Tarbonara's debt circus. The fun never stops...", objectives = "Compete in Slot Mining at The Heaps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83527] = { id = 83527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winning is for Losers, Anyway", description = "This is the worst job I've ever had. And I used to work Turtle Toss at Darkmoon Faire.\n\nWe're not imprisoned here physically with shackles, but Tarbonara owns all of our debts. He imprinted the information on Debt Markers, which his goons hold on to in case any of us want to know where we stand.\n\nBut if you get a hold of those markers, we're all free. You'd have to crack some skulls to get them though, so I'll give you points for each of his goons bring down.\n\nYou like collecting points, don'tcha?", completion = "Everybody packed in? Good! This will definitely NOT get us pulled over.\n\nCan't praise you enough for this one, {name}. Really. Truly. The Gallagio is going to have an entire floor of gaming enthusiasts ready to go!", objectives = "Collect Debt Markers and free the Indenture Debtors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83528] = { id = 83528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Part of the Game", description = "Look. I know we're the ones that incurred our own debts, but Rosebud believed in us! With him, there was a light at the end of the casino floor.\n\nWith him gone... We're just two halves of a gaming genius, working for hire instead of salary.\n\nBut Zoomcart told us there's still a chance we could work the Gallagio. Is that true? If it is, Davey and I are in.\n\nProblem is that Davey and I's Debt Markers are held by the gaming commissioner himself: Kudd Milktooth. And he's deep in Tarby's pocket.", completion = "How much did you have to pay the get their debt markers?\n\nOh... Well then I guess we won't have to fill out reimbursement forms for you then!", objectives = "Collect Kayjay and Fantastic Davey's Debt Markers from Commissioner Kudd Milktooth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83529] = { id = 83529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallowfall Fishing Derby", progress = "Any bites, {name}?", completion = "These are some great catches, {name}! I can't wait to see what you catch next week!", objectives = "Catch these Trophy Fish before the Derby Dasher buff expires: Bismuth Butterling, Whispering Stargazer, Regal Dottyback.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83530] = { id = 83530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallowfall Fishing Derby", progress = "Any bites, {name}?", completion = "These are some great catches, {name}! I can't wait to see what you catch next week!", objectives = "Catch these Trophy Fish before the Derby Dasher buff expires: Bloody Perch, Roaring Anglerseeker, Spiked Sea Raven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83531] = { id = 83531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallowfall Fishing Derby", progress = "Any bites, {name}?", completion = "These are some great catches, {name}! I can't wait to see what you catch next week!", objectives = "Catch these Trophy Fish before the Derby Dasher buff expires: Dilly-Dally Dace, Dornish Pike, Azj-Kahet Slum Shark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83532] = { id = 83532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallowfall Fishing Derby", progress = "Any bites, {name}?", completion = "These are some great catches, {name}! I can't wait to see what you catch next week!", objectives = "Catch these Trophy Fish before the Derby Dasher buff expires: Crystalline Sturgeon, Specular Rainbowfish, Sanguine Dogfish.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83534] = { id = 83534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ain't No Warm Up Act", description = "Can't believe Revilgaz scheduled us first! No one shows up for the first band!\n\nWhatever. You the one that oldhair Marty mentioned? He already gave me the lowdown on your plan to keep the Gallagio from going to auction. Seems ridiculous. Which makes it our kinda plan.\n\nLet's make a deal. Our manager dumped us when the casino deal went south, so YOU are gonna fill in for her today. Don't worry, couldn't be worse than any other job you've done.\n\nFirst thing on your list: gather us a crowd.", progress = "Hope you're making up crazy lies to get these people to see us.\n\nThat's what we'd do.", completion = "Great job, boss. You brought in a crowd, and then some.\n\nSecond thing on our list... You know how to play an instrument right?", objectives = "Spread the hype and gather a crowd for the Cellar Gnomes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83535] = { id = 83535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunder Party Rockin' Rumble", description = "Here! Take this Mecha-Trianbell!\n\nI don't care that you can't play an instrument because you WILL be playing this one.\n\nWhile we're jamming, members of rival bands will storm the stage to stop us. \n\nNot only will the Trianbell ring out in perfect pitch, it'll also blast anyone not in our band all the way to the cheap seats.", completion = "Best gig we've ever played! It was a dang warzone, huh?\n\nYou did good. Get oldhair's new deed, and we'll sign.", objectives = "Protect the Cellar Gnomes with the Mecha-Trianbell while they play.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83536] = { id = 83536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undertide Undertaker" }
quests[83537] = { id = 83537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geothermal Gem Treatment" }
quests[83538] = { id = 83538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excavation Liberation" }
quests[83539] = { id = 83539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeling Blue", description = "I fear... that it may just be me that remains, {name}. Or that the others are too far away to receive my missive.\n\nIt may be up to us to build an outpost here and see to the cleansing of the crash site.\n\nSo be it. It is just as well...", progress = "It's hard to describe what I feel right now.", completion = "Well done. That bag is quite useful, isn't it? I'm glad I thought to bring it with me.\n\nNow, on to the task at hand...", objectives = "Build the Kirin Tor outpost in the Tranquil Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83540] = { id = 83540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work the Line", description = "Not sure if your schnoz picked up what mine did on the drive over, but there were some delightful smells coming from the street below. \n\nProblem was, the crowds were too thick for me to find Gobdre anywhere.\n\nThat's where Noggy comes in. He's a pretty important fella these days, so I figure he'd have some sorta in for us.\n\nHe's generally an unfeeling scientist-type who doesn't spill secrets. But his pride is also fragile as my wife's Rumble figurines. \n\nGive it a poke and he should spill.", progress = "Did you just cut the line?", completion = "Noggenfogger gave you a personal recommendation letter, as well?\n\nHe's duller than I thought if he expects I'd let anyone jump the line.", objectives = "Get Marin Noggenfogger to spill the beans on Jojo Gobdre's whereabouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83541] = { id = 83541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Review Bombed", description = "Show me you ain't just talk.\n\nI give Diner Cards to each customer. They're supposed to fill it out with their reviews on my menu, and return it here. But I haven't seen any yet. \n\nFishy much? Definitely. And not the kind I like.\n\nGo. Fetch. Get my reviews back. I ain't budging an inch in the Gallagio's direction without them.", progress = "How'd they like the Junglevine-soaked Stormray?\n\nBet they said it was bitter. I knew that batch was bitter. Ran outta salt when I was cooking it.", completion = "The lazy diners I can understand.\n\nBut my rivals were taking cards because Tarbonara told them it'd run me off their turf? Really? Couldn't they just... cook better food instead?\n\nDoesn't matter. You're no chef, but I guess you pulled through.", objectives = "Retrieve 100 Diner Review Cards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83542] = { id = 83542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quick Gills for Gold Now", description = "Ah, crabs... I knew this would happen.\n\nThe diners overwhelmingly scored one dish above all others: pan-seared deepwalker thigh with blood-spiced confit algarian orbinid.\n\nLong name, right? I was hoping that would dissuade the customers from writing it on their cards.\n\nTrouble is that I can't make pan-seared anything without a pan, now can I? And I sold my best pan when the Gallagio deal fell through.\n\nWant me back on board? Then get my pan. Those deepwalker thighs ain't gonna sear themselves.", progress = "Blair and Chub Bass. The scammiest lovebirds you'll ever meet.\n\nBut they did source me some terrific fish.", completion = "You still ain't chef material, but you sure are real good at fetch work.", objectives = "Exchange Gold Fish for Gobdre's Prized Pan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83543] = { id = 83543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventuring in Khaz Algar", description = "We've got scouts in every corner o' Khaz Algar, an' they all report the same thing: trouble.\n\nSeems we got here just in time, eh?\n\nCheck the scouting map on the table behind ye and lend a hand where ye can.", objectives = "Review the Scouting Map to choose an area within Khaz Algar to support.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83546] = { id = 83546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Responsibility", description = "Today's the day for shiny shoes, {name}!\n\nWe've got our deed signatures. We've got support from the cartels. And we've got... my kids.\n\nMy wife was supposed to come with us today as well, but she slipped in the shower! Can you believe that? She'll be at the chiropractor all morning. I feel awful for her. Absolutely awful.\n\nWelp! Her loss! Let's pack up what we need and I'll drive us all over to the court room!", progress = "You look worried. You shouldn't be worried. I'm not worried.", completion = "Wow! Big crowd, huh?", objectives = "Pack up and drive to court.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83547] = { id = 83547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to the Neighborhood", description = "<A letter has been left in your mailbox. The handwriting is neat and smoothly flowing.>\n\nWelcome to Borogrove, {name}! I'm Llyssabel Dawnpetal, the local steward. I'll be helping you get better acquainted with the neighborhood.\n\nOnce you've settled in, please come see me at Town Hall.", objectives = "Speak with Llyssabel Dawnpetal at Town Hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83548] = { id = 83548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Isle of Dorn", description = "Survivors from the attack on Dalaran are beset by nerubians led by Queensguard Zirix.\n\nLend your aid to protect whomever remains.", completion = "We won't let the nerubians take any more of our people.", objectives = "Speak with Lady Jaina Proudmoore on the Isle of Dorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83550] = { id = 83550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ringing Deeps", description = "Speaker Brinthe has gone to The Ringing Deeps to see how the Machine Speakers have fared while she was away.\n\nShe has asked for adventurers to join her at the bottom of the Coreway.", completion = "Thank you for coming. This is more of a mess than I expected.", objectives = "Meet Speaker Brinthe in The Ringing Deeps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83551] = { id = 83551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallowfall", description = "Anduin Wrynn hopes to gain the trust and aid of the Arathi in Hallowfall.\n\nHe will need help to win over these potential allies.", completion = "If you've come to ask for aid, I'm afraid you've found us in the midst of our own crisis.", objectives = "Speak to Faerin Lothar in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83552] = { id = 83552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azj-Kahet", description = "An Arathi airship is stranded in Azj-Kahet following a vicious nerubian ambush.\n\nAid the survivors as they withstand the nerubian assault.", completion = "Just in time, {name}. We were caught off guard, now let's push them back.", objectives = "Speak to Faerin Lothar aboard The Reckoning in Azj-Kahet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83553] = { id = 83553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magic-stealing Kobolds", description = "I'm afraid that our \"clean up\" of Dalaran extends far from the shores of the Isle of Dorn.\n\nIn my attempts to find you, I circled this island many times. During my flight, I sensed the magic of many familiar items--items that were formerly housed in Dalaran.\n\nDangerous items.\n\nSomeone or something has taken them who knows where. We must find these objects before innocent bystanders come to harm.\n\nFollow me.", completion = "We will begin our search here.\n\nI can feel faint arcane auras emanating from around and beneath this structure.\n\nThe kobolds must have found and brought them to this place.", objectives = "Meet with Kalecgos at Mourning Rise in the Isle of Dorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83554] = { id = 83554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trinkets, Curios and Other Powerful Objects", description = "The kobolds here could get up to untold mischief with the items they have stolen.\n\nTake what you can back from them by... whatever means you see fit.\n\nWhile you deal with the kobolds around Mourning Rise's grave sites, I will go underground and search Kriegval's Rest and do the same.\n\nMeet me near Kriegval's Rest when you have secured the Kirin Tor artifacts the kobolds stole.", progress = "We must search and reclaim what we can. Even the smallest curio could be meaningful to someone... or dangerous.", completion = "I am shocked to see how much they managed to pilfer in such a short time.", objectives = "Reclaim stolen Kirin Tor artifacts from the kobolds in the Mourning Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83555] = { id = 83555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Necklace", description = "<The gem pulses with arcane energy, hinting at ancient magic woven into its very core.>", completion = "The kobold that had this was dead, did you say?\n\nThat... does not bode well.", objectives = "Return the necklace to Kalecgos at Mourning Rise in the Isle of Dorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83556] = { id = 83556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maybe You Shouldn't Touch That", description = "This necklace...\n\nIt is clearly full of powerful magic, but... it is elusive--as if it is hiding its origin from me.\n\nYou take another look. Maybe there's something obvious I'm missing.", completion = "It was foolish of me to let my guard down. \n\nDo not be alarmed, {name}, but this appears to be a... pocket dimension.\n\nIf the kobolds that met their demise here are any indication, it may be difficult to return to the Isle of Dorn.", objectives = "Investigate the Emerald Necklace in Mourning Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83558] = { id = 83558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Casino Court", description = "I'm all set to make our case. Just one tiny, little, minor thing to let you know about...\n\nThere's a bomb under my desk here.\n\nDon't be alarmed! It ain't the first time this has happened. But there's a lot of people here, and I'd hate to interrupt the proceeding for one little explosive.\n\nTake this X-Plo-Dar 64k. Use it to trace the bomb's signature back to the goblin with the trigger.\n\nMy lawyer's instinct is telling me that the culprit behind this explosive is also Rosebud's killer. Just a hunch.", progress = "Have you found the source yet?", completion = "Tarbonara? He's the bomber? ...Really?\n\nOnly reason I'm so surprised is because it felt too obvious!", objectives = "Use the X-Plo-Dar 64k to reveal who's holding the bomb's trigger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83563] = { id = 83563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coffee is for Closers", description = "You've got us the hard evidence we needed. All that's left to do is reveal Rosebud's killer to the judge.\n\nI imagine Tarbonara won't go down lightly, so be prepared for one of any number of goblin-like reactions.\n\nYou know what I mean. Explosions or cannons or crying or casino heists or whatever. I'm not worried though, you seem capable.", progress = "I had a feeling this would be a great case.", completion = "What did I say? I said to be prepared for a goblin-like reaction. And, oh boy, did we get one.\n\nAs you can see, everyone followed Gazlowe into scuffling with Tarbonara's goons. We did pretty good, yeah?\n\nMyself? I'm heading to the Gallagio's entrance. The new deed holders are all up there, and I want to wish them well before you and I are both promoted from lawyers to customers.", objectives = "Defeat Tarbonara Fizzlecrank, and ensure Judge Landro notarizes the new Gallagio deed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83566] = { id = 83566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, That Casino!", description = "You'd make a good lawyerer, you know that?\n\nHah! Just kidding! The real industry secret is that there's no such thing as a good lawyerer!\n\nWhy don't you join me at the Gallagio's entrance? It'll be a nice send off for the kids who are gonna run this place now.\n\nNot to mention that we should actually hand them the notarized deed!", progress = "You teary-eyed because our adventure is over?\n\nOr because you were secretly hoping the place would go to auction, and you'd have a chance to buy it up?\n\nBet it was the latter! Hah!", completion = "Sometimes it feels like there's a never ending stream of problems to solve coming out of the proverbial sewer drain. Doesn't it, {name}?\n\nBut this one... Well, let's just say that this one feels like a personal favor to all of Undermine.\n\nAin't no key to the city, but Marty wanted to pass on one his best lawyerin' outfits to you. Wear it with pride, kid.", objectives = "Hand the Gallagio over.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83569] = { id = 83569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death and Taxes", description = "He just... exploded...\n\nIf a goblin's gotta go, that's the way. All I can say for poor Rosey. And that I'm gonna miss him. AND that we're gonna find out who did this!\n\nBut the more immediate pickle is this: Who owns the Gallagio now?\n\nIt's time to turn to an expert on legal mumbo jumbo. The State of Undermine assigned a public defender to us for the court case tomorrow, a fella named Zoomcart. He's all we got.\n\nTake what's left of the deed to his office in Hovel Hill, and sort this out.", completion = "I assure you, I'm usually drowning in my paperwork far more figuratively than I was a moment ago.", objectives = "Meet the State of Undermine's assigned Public Defender.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83587] = { id = 83587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Chance to Strike", description = "<The child-like spider presents you with a sealed scroll. The sealed letter bears the markings of the Vizier.>\n\nThe balance of power is shifting in Azj-Kahet. The Queen grows more unstable by the day and I fear we must act before our opportunity to stop her slips from our grasp. \n\nMeet me at the Royal Apothecary when you receive this letter.", completion = "I would have rather sent my personal attendant to fetch you but the situation demands the utmost discretion.", objectives = "Meet with the Vizier at the Royal Apothecary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83616] = { id = 83616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Entrenched", description = "And now the other piece to this coup.\n\nI've been operating under Grand Overspinner Antourix's mandibles for a while now. She's entrenched in Rak-Ahat, and thinks nothing can touch her at the top. She has already refused to submit to Ren'khat.\n\nEven she knows that if Ren'khat has the backing of the throne then it is only a matter of time. Let us expedite her attempts to oust this upstart.\n\nSee how quickly they turn on each other.", progress = "An overcrawler? Here? In MY dominion?! Minions! Slay them!\n\nWait! Wait...\n\nYou might be useful...", completion = "Ugh. I don't have time for any of this.", objectives = "Offer your services to Grand Overspinner Antourix against Ren'khat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83627] = { id = 83627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Beginning of Something Beautiful", description = "<This seems like it would be of interest to a nerubian alchemist. \n\nAscension is their specialty, and this may be key to understanding more about the process.>", completion = "Hm? What? Well this is fascinating...", objectives = "Take the Vial of Skyrazor Blood to Shalba.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83628] = { id = 83628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tense Recovery", description = "Things with these strangers are... tense. We do appreciate being allowed to take cover here in their camp. But they only seem to tolerate us at best. We offered to share our supplies, but that offended them, somehow.\n\nMy sister is gravely wounded. I can see herbs I could use to help her in that tent over there, but that giant snail is blocking the entrance. I can't get to them.\n\nI asked the guard on the hill for aid, but all he did was glare. I don't know what to do! Perhaps he'll listen to you?", completion = "You are not unwelcome, stranger. I am the last.", objectives = "Speak to the strangers to improve relations with the Arathi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83629] = { id = 83629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Respite", description = "This was once a great lake. Over time the roots ruptured its floor, and drained the water away. I have lived here for all of my lifetime and witnessed it all. But now, darker changes have come.\n\nSometimes changes comes with death. Decay is natural.\n\nBut the mites that feed upon my people are not. They spread an odd infestation that makes my bark feel like it crawls from my body.\n\nDestroy these mites, so that I may rest without fear of their mouths upon my sleeping form.", progress = "The sound of their gnawing fills me with dread.", completion = "It is quiet. Perhaps I will rest, now, with my people.", objectives = "Kill 15 Feasting Mites for Goehi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83632] = { id = 83632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rings of Memory", description = "I appreciate what you have done. Do not worry--I am not finished yet.\n\nIf you please, take this root to those who sent you. They can read the history of my life within the rings of wood therein. My life is one of many in the tapestry, but we are all intertwined. \n\nThese strangers you encountered may be reclusive--secretive even--but they understand this tapestry like no other, and guard it with their lives.", progress = "Did you find the ancients?", completion = "Goehi sent this root, yet was still alive...\n\nI understand. His story is safe with us.", objectives = "Bring Goehi's Root to Wild Camp Or'lay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83639] = { id = 83639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Open Communications", description = "You understand that others lead lives different to your own. Our ways restrict us. Our traditions are not for the ears of strangers. I have only spoken to you at all due to Orweyna's word. But I can feel On'hiea's disapproval from here.\n\nIt is uncomfortable to have mysteries at times. It is why so many fear the dark. It is unknown.\n\nI know I must seem cryptic. But our ways do not mean we are offended by the Arathi. They are creating tension where it does not exist for us.", progress = "I can't leave my sister like this.", completion = "I can't believe this was just a simple misunderstanding. I shouldn't have made assumptions. \n\nThank you for easing my mind--and for helping my sister.", objectives = "Speak to Ysabel and clear up the misunderstanding.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83641] = { id = 83641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trapped Between Life and Death", description = "A pocket dimension. This is old magic.\n\nMalygos used pocket dimensions on occasion when he did not wish to be disturbed.\n\nThey were mainly used by mages as research spaces or for testing dangerous spells. Or if a mage wanted to hide what they were doing...\n\nI wonder who made this one? I suppose it doesn't matter. We need to get out. \n\nThankfully, every pocket dimension has an exit. Though, it is normally well hidden.\n\nLet's find it.", completion = "Look! Whatever magic was left in that necklace is gone now. And with it, Kel'Thuzad's mirror image.", objectives = "Find a way out of the pocket dimension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83643] = { id = 83643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Somehow We Survived", description = "What we experienced in Kel'Thuzad's pocket dimension is a timely reminder of what can happen when magic is used without regard to ethics or regulation.\n\nTo me, this underlines the importance of the Kirin Tor.\n\nBut, on the other hand, Kel'Thuzad was Kirin Tor. It is also a reminder of how power corrupts.\n\nNow that we have made sure these artifacts will not cause anyone else to go on an unexpected trip... Let's return to Aethas. \n\nPerhaps now more have responded to his letter.", completion = "It looks like more mages have arrived!\n\nThis gives me hope.\n\nI am sure Aethas will be relieved.", objectives = "Regroup with Kalecgos at the Tranquil Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83707] = { id = 83707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - 11.0 The War Within - Raid Finder - 1st" }
quests[83708] = { id = 83708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - 11.0 The War Within - Raid Finder - Nth" }
quests[83711] = { id = 83711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Conquest", description = "Tales of your prowess have reached even me, hero. If you fight as well as they say you do - then I reckon you would be even better with one of my creations. Write your name in history. Return when you've proven yourself both skilled and honorable.", objectives = "Obtain Conquest in Rated Arenas and Battlegrounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83715] = { id = 83715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claimed Salvage" }
quests[83716] = { id = 83716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beneath the Roots", description = "I am glad to see you are well, {name}. I have recently received word that a number of the Aeroknights have taken shelter in a camp close to where the airship was seized in mid-air. \n\nWould you check on them?", completion = "We are doing our best with what we have. The owners of this camp have allowed us sanctuary, but there are no smiles here.", objectives = "Find the camp sheltering the Aeroknights in western Azj'kahet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83718] = { id = 83718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eggstraction" }
quests[83719] = { id = 83719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those Are Chitin Words", description = "Well now, this is certainly an interesting specimen. It seems the original creator who worked on this creature made grave errors in balancing the genetic materials. No wonder the creature you encountered was an abomination. What terrible technique!\n\nWith the right materials however, I may just be able to perfect it. Siesbarg here will be our test-subject. Perhaps his Ascension will finally catch the attention of those in charge of administering promotions!", progress = "Chitin samples will help define the strength of Siesbarg's new form.", completion = "I will put this chitin to great use!", objectives = "Collect enough Nerubian Chitin for Shalba's experiment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83720] = { id = 83720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venom? More Like Get 'Em", description = "Now that we've acquired enough chitin samples to splice into the perfect armor, we need the perfect venom. Don't look at me like that. Our forms should always be powerful and capable of defending themselves!\n\nI'll begin incorporating the new carapace requirements for Siesbarg's Ascension while you harvest what I need. Do keep in mind though, it must be nerubian venom, specifically. I'm afraid beetles and spiders simply won't do this time around. \n\nAs for where you find it, well that's up to you.", progress = "Very good! This is exactly what I was looking for.", completion = "This will do nicely. Onto the final phase of my experiment!", objectives = "Collect enough Nerubian Venom for Shalba's experiment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83721] = { id = 83721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Small Ocean's Worth of Blood", description = "Excellent! The end draws near! But although we near completion, we cannot go without the most important part of this genetic equation--the blood. We need a small ocean's worth of nerubian blood. \n\nHowever, to make this new form foolproof, the blood must come from the strongest nerubians to exist. Whether skyrazor or Ascended, it doesn't matter. This will guarantee we have the best genetic material available.\n\nThe kind of material that Siesbarg deserves!", progress = "Our experiment nears fruition, overcrawler.", completion = "Brace yourself--you are about to witness perfection!", objectives = "Collect enough Nerubian Blood for Shalba's experiment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83722] = { id = 83722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consolation Flies", description = "Well... that's unfortunate.\n\nIt appears my experiment has failed and Siesbarg paid the price. Still, I am optimistic for the future I am destined to acquire. It's only a matter of time until I perfect my process. When I do, perhaps I shall engineer my own Ascension!\n\nWhile his physical form isn't what I intended, it appears Siesbarg's mind is intact. I'm certain he can still be of use. Take him. His new form can provide better service on the field of battle than in my tiny shop.", completion = "<After a heavy scoff towards Shalba, Siesbarg enthusiastically stands by your side.>", objectives = "Take Siesbarg off Shalba's hands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83723] = { id = 83723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Helping Hand", description = "Kalecgos's hypothesis that Dalaran's debris interferes with long-range teleportation seems correct.\n\nMage portals have appeared along the shore, but no one has stepped through them. There are likely mages trapped within the portals.\n\nOr, something mana hungry--like felhunters--may be being lured here by the release of Dalaran's power.\n\nWe must investigate. Mages of the Kirin Tor may be in danger. The felhunters are an acceptable risk.\n\nLet us not waste any more time.", completion = "I'm glad to see the scattered mages of the Kirin Tor answering Aethas's call.", objectives = "Help mages exit their portals on the Isle of Dorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83737] = { id = 83737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chromie's Time Trips" }
quests[83738] = { id = 83738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notorious with The Weaver", description = "Many many thanks for you from the Weave-mother. \n\nCome back to the Lair. I have good goods for you. \n\nI have webbed up and protected them, so no you worry!", completion = "Keep up the good good!\n\nThe Weaver also asks us to give you her \"compliments,\" but I find no \"compliments\" in here.\n\nMaybe I ate them? Apologies!", objectives = "Speak with Bobbin in the Weaver's Lair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83739] = { id = 83739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notorious with The General", description = "Word of your deeds has reached many of The General's acolytes!\n\nFind me at the Weaver's Lair. We have prepared a tribute for you!", completion = "Here! Accept these gifts as a tribute to your strength!\n\nIgitith ik tak'na!", objectives = "Speak with Aspirant Kiipka in the Weaver's Lair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83740] = { id = 83740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notorious with The Vizier", description = "The Vizier has asked me to provide you with additional resources towards your efforts.\n\nCome to the Weaver's Lair. I'll be waiting for you with a parcel.", completion = "The Vizier's compliments should be a more than sufficient gift for you...\n\nBut I suppose these goods would simply go to waste if not for his generosity. Take them. Be grateful.\n\nAnd do try to remain alive, overcrawler.", objectives = "Speak with Tulumun in the Weaver's Lair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83742] = { id = 83742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Attention", description = "Hail, soldier. General Anub'azal requests your presence at Siegehold immediately. He requires your expertise in the investigation of a sensitive matter.\n\nI am not at liberty to say more here. Seek out the General for further briefing.\n\nFor Azj-Kahet.", sourceObjective = "Report to General Anub'azal in Siegehold.", sourceObjectiveStatus = "unverified-source-field" }
quests[83743] = { id = 83743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Cold War", description = "A few mages have come but... I expected more to act on Aethas's call to action.\n\nBut perhaps that was wishful thinking.\n\nWe need more help despite what you and Kalecgos did at Mourning Rise. Aside from Kel'Thuzad's pendant, the kobolds' plunder was middling-powered artifacts.\n\nMeanwhile, there have been reports of powerful magical objects filtering through Azj-Kahet, meaning the nerubians must have scavenged Dalaran's crash first!\n\nWe must find these artifacts before they are used against us.", completion = "We may have arrived too late, {name}. For all of us.", objectives = "Travel to Azj-Kahet and meet with Lady Jaina Proudmoore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83749] = { id = 83749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delves: The Waterworks", description = "What a trip! Can ye believe how much exists below the depths here? \n\nThe Machine Speakers were telling me of problems they're having over at a place called the Waterworks. Sounds like kobolds are making trouble again. They're also storing some treasure deeper within the place.\n\nWhat do ye say? Let's go on an adventure and help out these folks!", completion = "In and out. No problems at all!\n\nExcept for this trapped chest in front of us.", objectives = "Complete the Waterworks delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83750] = { id = 83750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Zuramat the Obliterator", description = "_", objectives = "Find Zuramat the Obliterator and collect his soul stone in Azj'Kahet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83752] = { id = 83752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threats of Zekvir", description = "Someone's watchin' us, {name}. They put this chest here for us to find.\n\nLet me know when you're ready. I'll trigger the trap here to see just what exactly is going on.", completion = "Well, I'm not one tae let a little threat stop me from exploring farther. Looks like I got more investigating tae do. \n\nI'm sure I'll see you again real soon!", objectives = "Speak with Brann Bronzebeard to investigate the strange chest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83753] = { id = 83753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cannon Karma", description = "This is gettin' serious, {name}! Those pirate goons have a cannon and are threatenin' to blow us outta the sky!\n\nBut this may also be an opportunity.\n\nIf youse get rid of the monkey firin' the cannon, we maybe can get control of it for ourselves for some payback!", progress = "Ya better be tellin' me dem pirates is all gone!", completion = "Couldn't have done better myself. Youse should have a Kaja'Cola to celebrate.", objectives = "Bilge Rat attack disrupted and Cannon Master Jin'chu eliminated.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83755] = { id = 83755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delves: Nightfall Sanctum", description = "Good tae see you again! I've run into a bit of a mess since we last met.\n\nSome nerubian called \"Zekvir\" wants the expedition to stop explorin' this land. You know what that means. We've got to explore even more!\n\nThese Order of Night cultists might have information regarding Zekvir. Let's go to Nightfall Sanctum and see what we can find out.", completion = "Hrm... So this Zekvir fellow seems tae be lurking in the dark of a lot of places we're exploring. He might even be capable of empowering folk!\n\nWe'll have tae go deeper tae figure this out. Leave the legwork tae me!", objectives = "Find evidence of Zekvir within the Nightfall Sanctum and complete the delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83758] = { id = 83758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Fungal Folly", description = "We've got more reports of fungarians returning to a place we've dubbed \"Fungal Folly.\"\n\nExplore the cave and eliminate any threats you find.", progress = "Are you the one who grabbed the task for Fungal Folly?", completion = "Thank you for dealing with the fungarians. One day they won't be such a malfunction in our systems.", objectives = "Complete the Fungal Folly delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83759] = { id = 83759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Kriegval's Rest", description = "HELP WANTED\n\nKriegval's Rest has become overrun by kobolds! This once sacred resting place of the earthen must be restored.", progress = "Are you investigating Kriegval's Rest?", completion = "Kriegval's Rest is a sacred place to our people. Thank you for helping us restore it.", objectives = "Complete the Kriegval's Rest delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83761] = { id = 83761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delves: The Underkeep", description = "Who would've thought I'd be cozying up in a nerubian's lair!\n\nThere's a nasty named Zekvir threatening folks trying to explore the island. I've been asking the Weaver for any information she's got.\n\nSupposedly, there's a place called the Underkeep that might have records on him. Let's check it out and see what we can find!", completion = "Zekvir is an agent of Xal'atath! And he's trying to destroy any memories of Azeroth that he finds.\n\nThat makes our job of exploring more crucial than ever, {name}. We won't give up, not even with Xal'atath's toady chasing us!", objectives = "Find information on Zekvir within the Underkeep and complete the delve at any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83762] = { id = 83762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Critical Mass", description = "This is exactly what I had feared.\n\nThalen Songweaver's notes on the mana bomb he devised to devastate Theramore were under guard in Dalaran. Few knew of this.\n\nI argued they should be destroyed. But others argued if such a bomb was again created, we would need them to disarm it.\n\nAnd now those notes are both the problem and the solution. \n\nThankfully, I have read these notes, {name}. I will walk you through disarming the mana bomb.", completion = "My faith in you is never misplaced. Well done.", objectives = "Help Lady Jaina Proudmoore disarm the mana bomb in the Breathing Pit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83763] = { id = 83763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserve the Legacy", description = "The larger threat has been contained, {name}, but I believe there are still other artifacts important to our legacy--good and bad--here in Azj-Kahet.\n\nWhile they are still dangerous, their knowledge may benefit us in the long run. And, we must not allow the nerubians to profit from what they and Xal'atath did to Dalaran.\n\nLeave no dark corners here in the Breathing Pit unexplored, {name}.", progress = "We must reclaim what we can of the Kirin Tor's legacy.", completion = "What have you found?\n\nThalen Songweaver's notes. \n\nThe rest will be kept safe, but these notes...\n\nI will see to their destruction myself.\n\nThank you, {name}.", objectives = "Collect valuable items from the Breathing Pit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83764] = { id = 83764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Powerful, Too Dangerous", description = "Some of the relics the nerubians now possess were housed in carefully-designed containment vaults on Dalaran. That is how dangerous and powerful they are.\n\nWith those vaults gone, the only course of action we can take is to destroy them.\n\nIn hindsight, it seems a grave mistake to have gathered so many powerful artifacts in one place--even if that place was Dalaran.\n\nI would trust no one else with this task, {name}. Find and destroy those artifacts.", completion = "Thank you, {name}.\n\nIn the future, the Kirin Tor must find better ways to study and safeguard magical artifacts.", objectives = "Find dangerous artifacts scattered around in the Breathing Pit and destroy them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83766] = { id = 83766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Dread Pit", description = "Two things are bad for business. Earnest competition and the Dread Pit caves. We need someone to deal with the latter!\n\nSomething bad is going on here. We lost a bunch of workers in this cave.\n\nWe need you to deal with the threat, so we can keep business booming!", progress = "Glad I finally found someone to check out the Dread Pit!", completion = "You took care of them spiders in the Dread Pit? Great!\n\nI'll get to work on figuring out a better name for that place. \"Dread Pit\" just ain't catchy enough.", objectives = "Complete the Dread Pit delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83767] = { id = 83767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: The Sinkhole", description = "We have reports of large amounts of kobyss gathering towards a lair called the Sinkhole. There are concerns they plan to attack the smaller coast villages when they get the chance.\n\nThere's a hefty reward for anyone who can go into the Sinkhole and stop whatever they're planning!", progress = "Beware of what lurks within the Sinkhole.", completion = "Thank you for the aid. It's hard to aid everyone in Hallowfall given the current situation.\n\nHopefully, the kobyss will think twice about trying any further attacks.", objectives = "Complete the Sinkhole delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83768] = { id = 83768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: The Skittering Breach", description = "Call For Any Who Can Swing a Sword or Sling a Spell!\n\nThe nerubians perform foul rituals in the shadow of our once beautiful Aegis Wall. Word is that a dark temple dedicated to their cursed gods rests beneath the ground. \n\nSomeone must investigate this foul place and put an end to their schemes.", progress = "The Skittering Breach is a dangerous place. Be on your guard if you're going in.", completion = "You survived the Skittering Breach? I know many a Lamplighter who was forced to retreat from that foul place.\n\nYou've made this land safer. Thank you.", objectives = "Complete the Skittering Breach delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83769] = { id = 83769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Mycomancer Cavern", description = "Spice Help Needed!\n\nFungarians in the Mycomancer Caverns have been raiding spice crates bound for Lorel's Crossing. Someone needs to go into those caverns and push back the fungarian menace! \n\nWill pay well.", completion = "I heard the fungarians had been thinned out by someone recently. Thank you!", objectives = "Complete the Mycomancer Cavern delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83770] = { id = 83770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Spiral Weave", description = "A lot of us survivors have heard stories about the Spiral Weave. Seems like it's a place where the nerubians have some heavy military operations going on.\n\nTaking the fight to them would help put a serious dent in the nerubians' war plans.", progress = "You're going into the heart of a nerubian military base. Be careful.", completion = "You did it! That should give our forces on the surface a bit of a reprieve.", objectives = "Complete the Spiral Weave delve on any difficulty", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83771] = { id = 83771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Tak-Rethan Abyss", description = "WEAVER'S ORDERS\n\nThe Tak-Rethan Abyss continues to be a place of great unrest and trouble.\n\nSomeone must keep the threats in check before they interfere with our plans.", progress = "Are you investigating those kobyss?", completion = "Fine work. I shall let you know if I require any further kobyss-related purges.", objectives = "Complete the Tak-Rethan Abyss delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83773] = { id = 83773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farewell, City of Magic", description = "Not all the Kirin Tor's issues can be solved in one day.\n\nBut one way we can act is to honor those who have fallen. After speaking with everyone here, we have cobbled together a ceremony to send off those we have lost... and Dalaran.\n\nWe would be honored if you would join us and participate in remembering our fallen comrades in the Kirin Tor.", progress = "One thing I am sure of is that the Kirin Tor's future is not another floating fortress in the sky.\n\nNo, whatever path the Kirin Tor chooses, it will be firmly rooted here, on Azeroth, among the people it serves.", completion = "I will stay here with all of you and help however I can.", objectives = "Place mementos brought by Dalaran survivors on the boats in the Tranquil Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83775] = { id = 83775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Growth II", objectives = "You have grown considerably, but you may be in need of my services. Eternus has approved a dispensation of Bronze for experienced Timerunners. I can empower your equipment, if you require.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83776] = { id = 83776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Growth III", objectives = "It feels mere moments since last we spoke. I have additional Bronze for you. You may do with it what you wish.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83777] = { id = 83777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Growth IV", objectives = "Timerunner! You have come far. Is this the end of your journey in this timeline or just the beginning? I can continue empowering your equipment to greater heights or you may decide to trade your Bronze with the other Infinites within. The choice is yours.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83793] = { id = 83793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid the Jinyu", progress = "Our people are restless to flow with the waters. Lend aid to our village, that we may move with the currents.", completion = "We are grateful for your offerings." }
quests[83794] = { id = 83794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soggy Celebration Crate", description = "<The crate is pretty wet and smells a bit fishy, but looks to be mostly sealed tight. Alyx would appreciate the supplies returned.>", progress = "Oh, I am so busy. But what can I help you with?", completion = "Oh, you found a missing crate! That's great!\n\nWait... why does this smell like fish? Actually, I do not want to know. \n\nI really appreciate you returning these. If you find any more please bring them to me.", objectives = "Return the Soggy Celebration Crate to Alyx.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83795] = { id = 83795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid the Hozen", progress = "You hozen friend, wikket? Give da jingle jings!", completion = "Woot! You a real nibby wookin, wikket!" }
quests[83825] = { id = 83825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring A Grand Tale", description = "It was terrible! My book was shredded, and the pages flew everywhere! \n\nI saw some caught in the sand devils that went down the tunnel, others caught on adventurers heading out to face the big monsters in Tanaris, and others are scattered around here. Maybe that bird thing of yours could find them?\n\nPlease help me get the pages back so I can restore my book!\n\nOh, and watch out for that shady Cravitz Lorent. He's selling new copies for a hundred gold under the Fashion Frenzy stage. Robbery!", progress = "Were you able to find all the pages and repair my book?", completion = "Oh, it looks almost new! You did a great job. I can't thank you enough. \n\nAlyx said to give you this for your help! And if we could keep this between us, that would be great. No need to let my sister Addie know that I almost lost her gift.", objectives = "Return a Green Hills of Stranglethorn to Raenie Fizzlebog outside the Caverns of Time", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83827] = { id = 83827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silence the Song", description = "The sirens... they're out there! And I wonder... was it the crystal or these creatures that the Kul Tirans named this isle after?\n\nWhichever it may be, these sirens' call has lured many of our forces to their doom.\n\nOur goblin allies have prepared a device to remove the control they have over our troops.\n\nEliminate these \"sirens\" and dispel the charm that holds our troops captive.", progress = "Have you eliminated the siren threat?", completion = "Excellently executed, {name}. No soul should succumb to such dreadful creatures again.", objectives = "Free 7 Charmed Troops and slay Macabea The Sea Banshee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83832] = { id = 83832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torn Dreams", description = "Hello again! I could really use your help here. \n\nA visitor by the name of Addie Fizzlebog had a book damaged by some time devils that swept through here last night. I am still dealing with all the other problems they caused and was hoping you could help Addie with her issue.", completion = "THE Hemet Nesingwary is here signing his Green Hills of Stranglethorn book. I was going to have him sign my copy, but then dust devils tore through the camp and shredded it!\n\nMy sister won't let me leave the camp on my own, and I couldn't stand to tell her that the book she gave me was ruined. I could really use your help!", objectives = "Seek out Raenie Fizzlebog outside the Caverns of Time.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83930] = { id = 83930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deworming Solution" }
quests[83931] = { id = 83931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battered Celebration Crate", description = "<The crate is pretty battered. It looks like at least one wolf chewed on its corner. Alyx would appreciate the supplies returned.>", progress = "Oh, I am so busy. But what can I help you with?", completion = "Oh, you found another of our missing crates!\n\nIt looks like you got to it just in time. A bit more and whatever animal was trying to get in would have spoiled the supplies. \n\nI really appreciate you returning these. If you find any more, please bring them to me.", objectives = "Return the Battered Celebration Crate to Alyx.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83932] = { id = 83932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Historical Documents", description = "Imagine having the chance to accompany Sky-Captain Elaena Lancekat on such a great adventure. This is the opportunity of a lifetime!\n\nBut if I'm going to write a book about this journey, I need to gather some historical information about this island.\n\nPerhaps you could collect any notes or documents that you find? Anything might be useful and tell us about the history of this place!", progress = "What did you find?", completion = "You've gathered so much valuable information. There were so many secrets to be uncovered here! \n\nI can't wait to start writing this book.\n\nBut I need to come up with the perfect title first...", objectives = "Add 12 Notes and Documents found on the isle to the Research Journal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83933] = { id = 83933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kaja'Coast", description = "Alright, we got the punch card to the Kaja'Coast and a pretty good reason to believe Venture's shmoozin' up to Gallywix a lot more than we thought.\n\nNoggenfogger said we'd find answers at those mines, and that means goin' down to the Kaja'Coast for a look.\n\nLet's go. We'll meet you over at Slam Central.", completion = "Darkfuse is watchin' this place.\n\nThey're hidin' somethin' here. Somethin' big.", objectives = "Meet Gazlowe and Renzik at Slam Central Station, then use the Coastside Drill to travel to the Kaja'Coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84001] = { id = 84001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cart Blanche", description = "Our mining team is making great progress. All our carts have already been loaded with ore samples and sent back to camp. \n\nThere's a problem though...\n\nNone of the carts made it to camp due to trouble on the tracks!\n\nPlease repair the tracks and collect any lost ore if you can so we can get those samples to camp.", progress = "Are the mine carts getting through now?", completion = "Excellent work, {name}. I knew you would find a way to solve this problem.", objectives = "Repair 2 Mine Tracks, clear 5 Crashed Mine Carts, and collect 12 Ore Samples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84020] = { id = 84020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mech in Need", description = "This mechsuit has seen better days. Maybe a skilled Machine Speaker could assist you. \n\nI know Speaker Jurlax has been assigning machinists to mechsuit maintenance lately. He probably has some advice for you.", completion = "Time and decay have wrought havoc on this machine.\n\nWith a bit of work, we might still be able to recover it.", objectives = "Bring the Malfunctioning Mechsuit to Speaker Jurlax in Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84021] = { id = 84021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machine Without Cogs", description = "Diagnosis: This machine's movement is impaired.\n\nWe must get it moving again. I'm going to need some replacement parts. The gears must keep grinding.", progress = "Did you bring the parts we need?", completion = "Precisely what I need: the right part of the right job. \n\nThis should work.", objectives = "Bring an Overclocked Gear-A-Rang Launcher to Speaker Jurlax for parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84022] = { id = 84022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uniting Severed Threads", description = "You have done well to ally Anub'azal and Nizrek to our cause.\n\nIt is time that we solidify this triumverate relationship between us all. We will conference via shadecasters. Activate them when you're ready to begin.", progress = "I wonder how our three potent personalities will work together. Only time will tell, I suppose.", completion = "I expected far more verbal dueling than what occurred. To be so willing to work with one another must mean these times are dark indeed.\n\nWe have a long road ahead of us. I will say plainly that your help has been invaluable. It may end up being the thread that allows my people to survive.\n\nThank you.", objectives = "Join forces with the Weaver, the General, and the Vizier to forge the Severed Threads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84023] = { id = 84023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orienting Ourselves", description = "The machine moves without intent.\n\nLet us guide it toward purpose.\n\nDeliver direction unto this device.", progress = "Do you bear spatial omniscience?", completion = "This will lead our way.", objectives = "Bring a Synergistic Brewterializer to Speaker Jurlax for parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84024] = { id = 84024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clutching Control", description = "The machine breathes without life.\n\nWe must provide ours.\n\nFind a conduit for the will of the divine.", progress = "Do you wield a tool of influence?", completion = "This will channel our predilection.", objectives = "Bring a Burin of the Candle King to Speaker Jurlax for parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84025] = { id = 84025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repurposed, Restored", objectives = "The machine is complete anew, its purpose restored.\n\nYou who have staunched its suffering are charged with carrying on this purpose.\n\nMay its metal never yield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84084] = { id = 84084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Pinch", description = "Dust is the foundation of the art of enchantment. Where novice enchanters turn up their noses at such a common material, a master understands its versatility.\n\nBring me Storm Dust. No matter our expertise, we must always return to the fundamentals.", progress = "Have you collected the requisite dust?", completion = "Gratitude. It is good to see a fellow enchanter who appreciates the basics.", objectives = "Collect 20 Storm Dust and deliver it to Nagad in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84085] = { id = 84085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of Potential", description = "As enchanters, we do not merely trade in runes or wands. Our true commodity is potential. We take the power of possibility and infuse it into tangible forms.\n\nFor this, Gleaming Shards are essential. I require several to continue my work.", progress = "Where dust offers versatility, shards confer potential.", completion = "Acclamation. These will power many useful enchantments.", objectives = "Collect 10 Gleaming Shards and deliver them to Nagad in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84086] = { id = 84086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rare Necessity", description = "Occasionally, we are called upon to provide our greatest and most powerful boons. For these, I require a Refulgent Crystal.\n\nTrue, such crystals are rare, but necessary for us to reach the heights of our art. Worry not, it will not be squandered.", progress = "Once in hand, I will ensure it is put to worthwhile purpose.", completion = "Beautiful, yes? I'm sure you could sense the potential this might unlock.", objectives = "Collect 1 Refulgent Crystal and deliver it to Nagad in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84087] = { id = 84087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Level 26" }
